// ============================================================
//  Cuven Transfer — Cloudflare Worker 单文件版 · Cuven Bangkok（单机）
//  部署: dash.cloudflare.com → Workers → 创建 → 粘贴本文件 → Deploy
//        零绑定：不需要 wrangler.toml、不需要 Durable Object 迁移、不需要建 D1 库
//  · GET  /                   可视化面板（部署 / 传输 / 配置）
//  · GET  /rc-worker.js       采集线程（网络往返 + JSON 解析 + IndexedDB）
//  · POST /api/rc             浏览器 → Worker → VPS rclone rc 代理
//  · POST /api/dropbox/token  Dropbox 授权码换 rclone token
//  v4 新增: 智能并行调优
//    - 启动前 operations/size 扫描源目录，按平均文件大小选并发/分块/缓冲
//    - 内存预算钳制（先削分块再削并发），避免 VPS OOM
//    - Dropbox 走连接串注入 chunk_size / batch_mode，批量上传避开 429
//    - 启动前 mkdir 目标目录，网盘里立刻可见
//  v5 可靠性与手感
//    - 请求层：25s 超时 + 只读接口三次退避重试，写操作绝不重试（防重复任务）
//    - 刷新/切后台后按 jobid 接回原任务，路线与配方一并恢复
//    - 传输期间申请 Wake Lock，回前台立刻补一次轮询
//    - 轮询自适应：传输 1s / 空闲 4s / 后台 6s / 故障指数退避到 15s
//    - 停止需二次确认，3 秒自动复位
//    - 完成后可「核对两端」比对文件数与字节数（async 批量模式尤其需要）
//    - 文件列表按名字增量更新，不再每秒重建 DOM
//    - 速度做 EMA 平滑，数字用 rAF 缓动，曲线改贝塞尔
//  v5.1 UI 打磨（按 apple-design skill 逐条走查）
//    - 按压反馈拆两段：按下 80ms 即时到位，松手沿 soft spring 回弹（全部可点件统一）
//    - 坞 thumb / 胶囊宽度跟随改走 layout/soft 弹簧的 linear()，CSS 与 JS 同一条手感
//    - 弹层 materialize（blur+scale 同收束），transform-origin 锚定到触发控件
//    - 底部 scroll edge 渐隐：内容滑进坞下方先被洗掉，不再硬切
//    - prefers-reduced-transparency / prefers-contrast 各给降级；坞外控件补 focus-visible
//    - 弹层选项行高 38→42、垃圾桶 +8px 热区、.link 统一为天蓝下划线、color-scheme:light
//  v5.2 动效审计轮（animations skill 八类走查）
//    - 按钮文案接入 .vc 竖向 crossfade（开始传输/检测中 N/30/已复制/停止/换取…全量 16 处）
//    - 状态类内容（msg/err/stale/scanNote/connBar/jobbar）出场加轻 materialize，不再瞬弹
//    - 切页入场 440→280ms：高频动作压进 300ms 预算
//    - 弹层键盘导航高亮瞬移；.pop 手写曲线并入 --e-out；删除死令牌 --e-spring
//    - 审过不改：pillicon scale(0)（apple.com 源组件忠实编排）、mcard 退场的
//      max-height 收拢（罕见事件 + FLIP 替代过重）、.hl 宽度过渡（绝对定位小件，共享 thumb 惯例）
//  v5.4 色彩与触控轮（color 主 + surfaces / touch-and-accessibility 辅）
//    - 全部色彩令牌与彩色/灰阶字面量 → oklch；白云蓝改 --sky-lch 三元组驱动，
//      所有透明度派生（坞高亮/曲线/聚焦环/allset 玻璃）统一从它出，换主题只动一行
//    - P3 屏第一重点色 C 0.142→0.165（@media color-gamut，L/H 不动）
//    - 对比度修复（只动 L）：自检结果 ink-3→ink-2（2.5→4.6:1）、scanNote 与
//      胶囊读数换深一档蓝；新增 --sky-t 正文级蓝
//    - surfaces：弹层圆角 12−5 推导为 7、vhead/vrow 分隔线 retina 0.5px、底部渐隐缓入
//    - touch/a11y：全部可点件命中区补到 44px；折叠区 inert（Tab 不落进隐形输入框）；
//      allset 与详情层焦点进出 + Esc 关闭
//    - 豁免保留：纯白/黑与投影透明层的旧记法（合成层非调色板）、JS 内联字符串、
//      data-URI、meta theme-color；深色模式不做（本 App 定为纯浅色）
//  v5.5 部署与排障
//    - 一键部署命令回到页面里（按端口/密码即时生成的纯文本，非托管脚本，绕开当年的滥用判定）：
//      装 rclone → 建 1G Swap → 写 systemd 单元 → 自启，幂等，折叠盘承载
//    - 新增「排障」折叠盘：一键诊断（七项体检：rclone/服务/端口/本机认证/内存/磁盘/日志）
//      + 五条自修复（服务重启看日志 / 防火墙放行 / 按面板密码重写凭据 / 建 Swap / 重装 rclone）
//    - 维护里的「卸载」从占位文案换成真命令；折叠盘处理器抽成 bindFold 三盘共用
//    - 命令文本层约束：禁反引号 / 美元花括号 / 反斜杠（活在 Worker 模板字符串里），
//      shell 侧全走双引号 + { echo; } 组合写 unit 文件
//  v5.6 手动部署
//    - 部署盘加「一键 / 手动分步」方式切换（.sel 弹层，选择记 localStorage）
//    - 手动档六步各配复制键：依赖 → rclone → Swap → 前台试跑(可选) → 写单元 → 启动验证
//      第 4 步前台裸跑给排错用：报错直接上屏，此时即可回面板点检测；Ctrl-C 后再装常驻
//    - 两组内容用 reflow 连续切换 + inert 互斥；unitBlock/swapBlock 与一键档共用
//  v5.7 可靠性/性能加固轮（视觉零变化）
//    - 超时预算分级并两端贯通：Worker 侧 heavy 只读(size/list/about) 50s、
//      任务启动/建 remote 30s、轻接口 15s；前端对应 55s×2 轮 / 35s / 12s×3 轮，
//      修掉「大目录分析必超时」的真 bug；超时(504)与断连(502)分家、各说各的话
//    - Dropbox 换 token 补 20s 超时与网络兜底；非 JSON 响应报错说人话（反代拦截可辨）
//    - 断网/复网事件先于超时感知：offline 立刻亮 stale 条，online 立刻补一拍
//    - 服务单元加 --use-mmap（小内存 VPS 内存归还更稳）；API/HTML 补 nosniff 等头
//    - 走查确认 v5 已在位不重做：自适应轮询/指数退避/wakeLock/回前台补拍/
//      unhandledrejection/localStorage 守卫/图表环形缓冲/触摸监听 passive
//  v5.8 真机修虫（附首个全链路 E2E：mock rclone 后端跑通 自检→分析→启动→轮询→完成）
//    - 跑动期监控区的空卡片：verify-row 宿主卡在非 done 且无错误时整卡隐藏（#tailCard），
//      done 或出错才现身
//    - 胶囊落定 1-2s 后文字回缩：.pillhost.on .pillcopy 补 transform:none 终值——
//      pillSettle 清内联 transform 后原本回落到基类 scale(.5)；入场弹簧走内联不受影响
