//    - 展开层标题不再压在 × 底下：.surface .metric-header 让出 32px（× 绝对定位后
//      比 header 右内边距还往里 24px），× 竖直中心对到标题行光学中心
//    - 长文件名改「头部省略 + 扩展名常驻」：canvas 按实际字宽二分裁切，
//      省略号与扩展名之间零缝隙；CSS text-overflow 保留作兜底
//    - 关键：预算必须取自恒定宽度，故 .metric-title / .fname 都改成 flex:1 1 auto
//      （否则 .fname 缩到内容宽 → 每次重排预算变小 → 越裁越短）
