//           肉眼无差但把系统碎片化的根源去掉了；组件里不再出现裸 font-size
//    曲线   CSS 内 11 → 4（只剩 :root 的调色板定义）；JS 侧两支主曲线改从令牌读，
//           不再两边各写一份。all-set 那五支是逐帧标定的专属编排，明确不并入
//    时长   裸 ms 75 → 38，八个高频值上档（--d-16/2/22/24/26/28/3/34）；
//           单点值与弹簧 linear() 保持原样——硬套档位会毁掉调过的比例
//    仍超预算且没动的：字号 12 个角色 vs 预算 9（再合就要动 1–3px，属设计决策，
//           要动的三处是 31→34、20→22、16→17，等你点头）；裸 ms 还剩 38（多为一次性）
//    首屏 RMSE 9.6%：全部来自字号合并后的文本重排，非回归；功能链路已回归验证
//  v7.1 低速自动暂停
//    机制：rc 没有真正的 pause，暂停 = job/stop，恢复 = 用同一份 body 重发
//      （已传完的文件被跳过；代价是当时在传的那几个文件的分片进度会丢，已写进 ⓘ）
//    触发：总速 ≤10 MB/s 且持续 15s → 停 30s 再重发。两个护栏缺一不可：
//      ①(重)启动后 30s 宽限（爬坡期本来就慢）②必须持续 15s（单帧抖动不算）——
//      没有这两条，功能会在每次开传时自杀
//    降级：10 分钟内触发两次 → 判定被限速，关掉自动暂停并提示，交给「暂停/继续」手动
//    轮询接线：xPause 期间 tick 直接返回、checkJobs 不判完成——否则被 stop 的作业
//      会被当成「完成/出错」；变量名避开图表模块已占用的 paused
//    坑：开关接线若写在 let lowOn 之前会撞 TDZ，整个 init 块被中断（#go 都绑不上）
//  v7.2 修复：暂停后刷新页面接不回来（本条的版本号提升上轮被中断，随 v7.3 一起发）
//    根因：暂停时 jobs 被清空，saveJob 见空就存 null，恢复所需的 api/body 一起丢
//    改法：暂停态也落盘，restoreJob 先认暂停态再认运行态；自动档跨刷新可续冷却
//  v7.3 Supervisor（Durable Object）——常驻大脑落地
//    在这之前轮询/队列/低速自愈全活在浏览器标签页里，关页即停。现在：
//      DO storage  当前任务 / 队列 / 暂停态 / 低速计数 / 连接配置（权威状态）
//      DO 内存     近 120 个速度采样
//      D1          完成的传输历史（jobs 表，由 DO 在任务结束时写入）
//    Alarm 每 5s 巡检：采样、判低速、判完成、完成后自动推进队列；空闲不排 alarm，
//      手动暂停也不排（省额度）。5s 一轮 ≈1.7 万次/天，远低于免费额 10 万/天
//    rcCall 从 rcProxy 抽出，DO 与 HTTP 代理共用同一套护栏（SSRF/端口/白名单/分级超时）
//    密码只存 DO storage，snapshot 只回 { host,port,user,ready }，永不回传浏览器
//    部署需要 wrangler.toml（DO 绑定 + new_sqlite_classes 迁移），仪表盘直接粘贴不够
//    未绑 DO 时 /api/sv/* 返回 501，前端可据此回退纯本地模式
//  v7.4 前端接到 Supervisor + 队列 UI（DO 闭环完成）
//    适配层 svOn：null 未探测 / false 未绑 DO（走原纯本地路径，零回归）/ true DO 权威。
//      接上后本地低速状态机必须闭嘴（feedSpeed 首行 return），否则两边都判会双重暂停
//    轮询：一次 /api/sv/state 取代原来的 core/stats + job/status 两个请求；
//      带 since 只取增量采样（整环 ~3KB，1s 一拍就是 3KB/s 白费）；
//      页面隐藏时退避到 60s——监管在 DO 的 Alarm 上，浏览器不必在场
//    DO 侧两项省额度优化：字节数只留内存（每拍落盘 = 5s 一行写入，约 51 万行/月），
//      状态跃迁时才写 cur；alarm 尾部不再无谓 put
//    队列：转移页新增队列卡（可逐条移出 / 清空），「加入队列」按钮在 DO 可用时才出现；
//      入队时「已有任务在跑」不再是阻塞条件（那正是要排队的场景）
//    实测（伪 DO 运行时 + 真 Alarm 驱动）：关掉页面后 DO 独自完成任务、写 D1 历史、
//      并把队列推进到下一个；未绑 DO 时队列卡与入队钮均不出现且无报错
//  v7.5 修复：升级后看不到升级前就在跑的任务
//    根因：DO 模式下 tick() 在首个分支就 return，本地那套「空闲每 3 拍试一次 adopt」
//      永远走不到；而 DO 的 adopt 只在连接成功时调用一次——那一次没认领到
//      （VPS 忙 / 任务早于 DO 存在），界面就永远停在「空闲」，任务其实还在传
//    改法：svApply 在「无当前任务且已连接」时每 10s 让 DO 再认领一次
//    连带修一个更危险的问题：接管来的任务没有原始启动参数，暂停后无法重发——
//      等于按下去就回不来。现在接管态直接隐藏暂停钮（停止仍可用）并明确提示
//  v7.6 修复：自检弹窗把人送去配置页而不是传输页
//    自检时 remote 列表若没读到（VPS 正被大传输占满时很常见），rems 为空 →
//    CTA 变成「去添加 Remote」→ 跳配置页。有任务在跑时这判定明显错了：
//    现在只要 jobs/暂停态/DO 报告有任务，一律去「转移」页，按钮也改称「查看传输」
//  v7.7 修复：传输页闪一下就没了 + 一个会杀掉传输的隐患
//    ① 开机时本地先恢复/接管、监控区显示出来，紧接着 DO 首次快照返回「无任务」
//       （它还没认领），svApply 就无条件 showRunning(false) 把它抹掉了。
//       改为：本地已认出任务时不关闭显示，只是立刻催 DO 认领
//    ② 接管来的任务 api/body 为空，暂停后无法重发——却仍会走低速自动暂停，
//       等于把正在跑的传输直接停死且无法恢复。现在 lowSpeed 对这类任务直接放行
//  v7.8 极端情况自愈 + 降压（这两件其实是同一件：服务器挂了还猛敲，只会更糟）
//    降压四条：
//      ① 观看感知调速——有人拉 /state 时 5s 一拍，没人看降到 20s。多小时的传输
//         无人观看时不需要秒级精度，常态请求量直接砍掉四分之三
//      ② job/status 降频到每 4 拍一次（完成判定最多晚 20s），巡检请求少一半
//      ③ 失败后指数退避到 60s 封顶；401 认证失败直接退到上限（密码不会自己变回来）
//      ④ 暂停时不排 alarm（原有），浏览器隐藏时不轮询 DO（原有）
//    自愈三条：
//      ① 错误分类：连不上 / 超时 / 认证失败 分别对待，不再一律"重试"
//      ② 作业凭空消失（rclone 崩溃重启、VPS 重启后被 systemd 拉起）→ 用原参数自动重开，
//         上限 3 次、间隔 ≥60s，避免把崩溃循环放大成对服务器的连续冲击
//      ③ 接管来的任务没有原参数，无法重开 → 明确报错收尾，不假装还在跑
//    UI 如实呈现：连接不稳时显示失败次数与原因，自动重开后显示第几次
//  v7.9 修复幻影任务（v7.7 的过度修正）
//    v7.7 为了修"传输页闪一下就没了"，让本地认定的任务在 DO 说"没有"时不再清除。
//    但若那任务在 VPS 上确实已消失（rclone 重启过），界面就永远卡在半死状态：
//    作业条在、胶囊显示空闲、速度 0、进度 0%、stale 条一直数秒。
//    正确做法不是"保留"也不是"清除"，而是去核实：直接问 job/status——
//    还活着就继续显示并催 DO 认领；不在了就清干净并告诉用户原因。
//    同时补掉那个自相矛盾的显示：确认期间胶囊改为"正在确认"，不再停留在"空闲"
//  v8.0 紧急暂停（卸压）+ 人工授权恢复；修「卡在正在确认」
//    卡住的根因：核实任务是否存活时，只要拿不到答案就一律当"还活着"，
//      VPS 不可达 → 无限重试、界面永远停在「正在确认」。现在区分三种结果：
//      明确 not found = 死了（清理）／连不上 = 没答案（最多问 5 次就停手并说明）
//    紧急暂停：连续 6 拍无响应，或自动重开 3 次仍反复消失 → job/stop 停手、
//      停手、把巡检降到 60s 一次的最轻探活。这是极端情况下最有价值的动作：
//      服务器已经撑不住，别再打扰它
//    恢复必须人工点「恢复全部」授权，绝不自动——反复自动重启一台已经不行的机器
//      只会更糟。授权后清空失败计数、按原参数重开、队列解冻
//    停不掉的情况（当时就连不上）记 pendingStop，等探活成功后补做 job/stop
//  v8.1 手动紧急释压：作业条加「释压」钮，走与自动触发同一条 halt 路径
//    （停手 + 停手 + 降到 60s 探活），理由记为"手动"。会停掉正在跑的传输，
//    所以沿用「停止」的两段确认；恢复同样要点「恢复全部」授权
//  v8.2 「正在确认」加硬超时——不确定的状态不该无限期霸占界面
//    v8.0 只对"连不上"这一种情况做了 5 次上限；但若 job/status 每次都能返回、
//    却始终答不出个所以然（或返回形态与预期不符），仍会一直转下去。
//    现在：DO 报 cur=null 且本地确认不了，累计撑过 30s 就按"已经不在了"清理，
//    倒计时显示在提示里；认出真任务时计时归零
//  v8.3 移除队列 + 修「点开始传输没反应」
//    没反应的原因：启动前的守卫是 if (jobs.length) return —— 幻影任务让 jobs 非空，
//      于是静默返回、什么都不说。静默拒绝等于按钮坏了；现在明确告知
//      「已有任务在传输中，先停止它」或「当前任务暂停中，先继续或停止」
//    队列按要求整体移除：前端队列卡与「加入队列」钮、DO 的 enqueue/dequeue/clearqueue
//      与完成后的队列推进、以及早期会话遗留、前端从未使用的 D1 queue 表与路由，
//      一并清掉。DO 的 start 遇到已有任务改为直接报错，不再抢占也不再排队
//  v8.4 排查「启动失败：HTTP 403」
//    ① svRoute 原本把 request.body 当 ReadableStream 直接转给 DO 子请求——
//       这需要 duplex:'half'，失败方式不可预期。载荷只有几百字节，改成先读成文本
//    ② 错误不再只剩状态码：DO 返回的非 JSON 异常响应原样带出；前端在拿不到
//       JSON error 时把响应正文（去标签、截 120 字）附在消息里。
//       "HTTP 403" 这种光秃秃的信息说明响应里没有我们该有的 JSON 错误体，
//       也就是说拦截发生在我们的代码之外，必须把正文露出来才能定位
//  v8.5 修「正在启动…然后没有了」——错误被静默吞掉
//    根因：DO 的 start/resume 等失败时返回 { error }，但 json() 默认状态码是 200。
//      前端据此认为调用成功、不抛错，svApply 又见不到 cur 就当"没有任务"，
//      于是界面直接归零，错误一个字都没露出来。这是整条链路上最坏的一类 bug：
//      失败被伪装成成功
//    改法三层：① DO 侧凡带 error 的结果一律配 400；② 启动/恢复失败带上 rclone 原话
//      而不只是"失败"；③ 前端 svApply 见到 error 就显示，绝不当成空状态
//  v8.6 边缘错误码翻译
//    域名走橙云代理时，连不上源站会拿到 Cloudflare 生成的 HTML 错误页（520-524），
//    不是 rclone 的 JSON 回复。之前只能显示成"HTTP 521"，对用户毫无意义。
//    现在逐个翻译：521 = 端口上没有服务在监听（rclone 没跑）、522 = 连接超时、
//    523 = 解析到的 IP 不对、524 = 100 秒没回应（Cloudflare 硬上限）等
//  v8.7 识别「启动即崩溃」：轻接口全通、唯独 sync/copy 拿到 521
//    520-523 是连接被源站断开。此时补一次探活 + 读进程内存：若服务此刻又通、
//    且占用极小（刚重启的特征），就能断定 rclone 是在收到传输命令时当场挂掉
//    又被 systemd 拉起的 —— 这个结论单看任何一次调用都得不出来，只能靠组合判断。
//    对应提示直接给出处置：下调内存上限让并发/分块自动收敛，或加 swap
//  v8.8 修「无法启动传输」+ 全链路捉虫（DO 模式一轮走查，配 node 单测回归）
//    主案：停止钮从来没告诉过 DO —— 它只停本地 jobid。DO 的 cur 原封不动，
//      下一拍快照把任务复活；暂停中的任务更绝：jobid 为空、alarm 没排，
//      「停止」等于没按，DO 那份暂停态永生，「开始传输」被「已有任务」挡死。
//      现在 svOn 时先走 sv('stop')（DO 侧顺带清 halt、留 stopped 收尾），再做本地收拾
//    帮凶一：DO 的 adopt 会把 operations/size 扫描作业认领成传输任务 → start 报
//      「已有任务在传输中」。adopt 增加 exclude（前端传 sizeJobs）与 prefer（本地认出的
//      jobid 优先），svHello / 催认领 / 空闲重试三处都带上
//    帮凶二：v7.5 的「空闲每 10s 重试 adopt」在 v8.3 拆队列时被顺手拆掉——连接那一次
//      没认领到，升级前就在跑的任务永远不出现。已接回（带 exclude）
//    连带修掉的：
//    · svRoute 不转发查询串，/state?since= 的 since 一直被丢，增量采样形同虚设
//    · halt() 先清 jobid 再算 pendingStop → 恒 false；probe 的补停从未生效。
//      jobid 现在先抓进 halt 记录，probe 按它补 job/stop
//    · DO 判出的失败被显示成成功：cur 消失那拍 finish(doneFail) 用的是本地陈旧值。
//      complete/stop 现在落一条 last{ok,err,stopped}，前端按它收尾；停止另回空闲
//    · resume() 失败直接 return，自动暂停的 alarm 链被掐断，任务永远睡在暂停态。
//      失败改走 onMiss（退避重排，连挂照旧升级成紧急暂停）
//    · sv() 没有超时：边缘一挂，「正在启动…」永远挂在按钮上。重操作 65s / 轻接口 20s
//      （前端预算 > DO 最坏链路 30+15+15s，超时错误仍由靠近 rclone 的一端先说）
//    · DO 模式速度锯齿：前端 1s 一拍、DO 5s 一采，中间几拍字节没变，render 把瞬时
//      速率算成 0 喂进 EMA。快照带 statsAt，前端只在真有新采样时渲染
//    · DO 模式停止钮隐身：display 只有本地路径在管，起动/刷新后按不到。svApply 补上
//    · 前端 not-found 正则的反斜杠被外层模板吃掉（\s→s），"job not found" 永远匹配
//      不上，幻影清理只剩 30s 硬超时兜底。改 indexOf（与 RETRYABLE 同一条既有约定）
//    · restoreJob 双跑隐患：本地陈旧暂停态开机自动 resume，DO 那边同一任务也在管
//      （自动档还会自己续传）。现在 DO 在场时先要快照、以它为权威，打不通才走本地
//    · since 改用快照里的服务器时钟，客户端时钟偏几秒不再漏采样；sv 路径给
//      failStreak/lastOK 记账，DO 模式也有 stale 条与退避
//    · 隐私：cuven_cfg（含面板密码）不再写穿 D1，读取剔除并顺手清掉旧行——
//      /api/d1/state 无鉴权，密码只许活在 localStorage 与 DO storage（既有约定）
//  v8.9 深度审计（DO 并发正确性 + 免费额度 + 图表时间轴），配 5 组交错单测
//    ① DO 并发护栏：DO 单线程但 await 一个 VPS 子请求时输入门不拦新 fetch——
//       alarm 卡在 core/stats / sync 的 await 里时，用户点的 stop 会插进来清掉 cur，
//       长操作事后拿 await 之前读到的旧 cur 写回，就把已停止的任务复活了
//       （自动续传 + 停止竞态最致命：任务带着钱和文件继续跑）。凡「读 cur → 长 rc →
//       写 cur」的地方（resume / relaunch / alarm 主线）rc 回来后都用 curIf 复核身份：
//       还是同一个任务才提交；被停/换了就把刚起的作业当孤儿 orphanStop 掉，不写回。
//       单测用闸门 promise 精确编排「stop 插进 resume 的 rc」「stop 插进 alarm 的
//       core/stats」，验证不复活、不误判完成、不排僵尸 alarm
//    ② 防重复启动：两台设备几乎同时点开始，都过了「已有任务」判断 → 各起一份 rclone
//       作业（重复搬运、互相打架）。start 现在先落一个 provisional 占位 cur 再起作业，
//       第二个 start 撞见占位被挡下；占位对 snapshot 隐身，界面不闪空运行态；
//       起作业失败只清自己的占位，不误删他人后放进来的 cur
//    ③ 免费额度：前端 DO 模式活跃轮询从 1s 降到 2.5s。DO 自己 5s 才采一次，1s 轮询里
//       四拍是完全重复的（statsAt 去重后压根不渲染）；24h 传输按 1s 就是 8.6 万次请求，
//       叠上 Alarm 约 1.7 万会顶穿 10 万/天免费额度。降到 2.5s 后读数由 rAF 缓动兜住、
//       肉眼无差，请求量砍六成。本地模式仍 1s 采 core/stats 来平滑
//    ④ 图表时间轴不再撒谎：chartCommit 原本跟着 render 落点，DO 模式 render 每 5s 才来
//       一次 → 横轴 90 点窗口成了 450 秒却仍标 90 秒，曲线还冻 4 秒再跳。落点改由固定
//       1Hz 定时器驱动（commitsOn/Off，用缓动后的 dispSpeed + 最近的并行文件快照），
//       两种模式统一——横轴恒等于真实 90 秒；峰值改取原始速率不被缓动压低
//  v9.0 拆掉 DO 与 D1，回到 100% 本地
//    动因：绑定本身就是故障源。DO 要 wrangler.toml + new_sqlite_classes 迁移，
//      D1 要先建库，仪表盘粘贴一次就能跑的性质从 v7.3 起就没了；而这套东西换来的
//      唯一不可替代的能力，只是「关掉页面后仍有人巡检」。代价与收益不成比例。
//    删除：Supervisor 类（Alarm 巡检 / 认领 / 自愈 / 紧急暂停整套）、svRoute、
//      /api/sv/*；D1 层 DDL/d1Init/d1Route、/api/d1/* 与 kv·samples·jobs 三张表；
//      前端 svOn 适配层全部分支（sv / svApply / svHello / clearPhantom / verifyLocalJob）。
//      fetch(request, env) → fetch(request)，模块不再导出任何 DO 类
//    这批删除是安全的：DO 从来是叠在本地路径之上的（svOn===false 即原样走本地，
//      v7.4 就是按「零回归」设计的）。所以这一版做的是「把 svOn 恒定为 false 后
//      删掉死分支」，而不是重写——那条路径本身没动过一行
//    rcProxy 收敛到 rcCall：护栏（host/SSRF/端口/接口/分级超时）原本两份副本，
//      DO 走一份、HTTP 代理走另一份。DO 没了，留一份，从此不会各自漂移
//    释压 / 恢复全部 改本地实现（不让已有 UI 变孤儿）：连续 6 拍无响应 → job/stop
//      + 巡检降到 60s 最轻探活；恢复必须人工点授权。判定门槛与原 DO 一致
//    v7.3–v8.9 里所有 DO / D1 条目自本版起只作历史记录看
//    说清代价：页面关掉就没人监管了。VPS 上的 rclone 作业是 _async 起的，照跑不误，
//      重开页面 adopt() 会接回来；但那段时间里没有低速自动暂停、没有自愈重启
//  v9.1 修：接管来的任务，暂停钮不该亮
//    adopt() 接回的作业没有原始启动参数（api/body 为空），暂停 = job/stop 之后
//      无法重发 —— 按下去就回不来。这一条 v7.5 只在 DO 路径上判过（svAdopted 由
//      快照里 api 是否为空推出），本地 adopt 从来没判，暂停钮一直是亮的。
//      现在 adopted 由 adopt() 与 restoreJob 直接置位，暂停钮隐藏、低速自动暂停放行，
//      并在提示里说明只能停止。（附回归：拿旧文件跑同一条用例，pauseBtn=block）
//  v9.2 CPU：采集线程
//    /rc-worker.js 独立路由，不用 blob —— 这段代码若写进 HTML 模板字符串，
//      反引号 / 美元花括号 / 反斜杠会被外层吃掉（v5.5 栽过一次）。独立路由还能被缓存
//    它只接手两件事：① /api/rc 的往返与 JSON.parse ② IndexedDB 写入。
//      值钱的是前者里的解析：32 路并行时 core/stats 的 transferring[] 每秒解析一次，
//      是主线程上唯一一处会和 60fps 曲线抢时间的同步开销
//    判定、状态机、DOM 一概留在主线程。那部分是 v7.3→v8.9 一路打磨出来的，
//      搬进线程只会把已经修好的竞态重新引进来 —— 这是刻意不做的
//    线程起不来（老浏览器 / CSP / 加载失败）或中途炸掉 → RCWdead 置位，整体回落
//      主线程 fetch，两条路径共用同一个 unwrap()，错误措辞不分家
//    IndexedDB 接替原 D1 两张表：10s 一条速度采样（按 7 天滚动，本地没有额度问题，
//      限的是磁盘）+ 每笔传输历史。读取口 Cuven.history() / Cuven.samples()，
//      还没有对应界面 —— 做不做成「最近传输」卡片是设计决定，等点头再排
//    localStorage 写入合并 120ms + pagehide/隐藏时强制落盘：saveForm 挂在 input 上，
//      逐键 setItem 等于每敲一下做一次同步磁盘 I/O，中文输入法连打能看见掉帧
//  v9.3 GPU：合成与跳过
//    摞起来的卡片不再逐帧重建曲线：.pile 的卡只露 9/18px 的边，第 3 层往后 opacity:0,
//      曲线一个像素都看不见。restack 打 __off 标记，chartLoop 跳过它的
//      chart.update / disp 缓动 / 文字重排。32 路并行折叠时，每帧 SVG 路径重建
//      从 32 次降到 1 次 —— 这是本页最大的一处白烧
//    设备档位探测（逻辑核数 / 内存 / 有无可用 GL 上下文）写到 html[data-tier]，
//      启动时读一次，之后 CSS 与 JS 各自取用，绝不逐帧再问。low 档只动两处最贵的：
//      backdrop-filter 20px→10px（移动端每帧重采样整块底图，是量级差）、
//      曲线三层叠只留主描边（大半径 round-join 在弱机上会掉到软件光栅）
//    .plot / .ms-chart 补 contain:layout paint（不含 size，避免塌高），
//      一条曲线重绘不再把整页拖进 layout
//    未做：把主曲线改 canvas / WebGL。四层描边的观感是逐帧标定出来的，
//      为了一个 1Hz、90 点的折线去换渲染后端，收益填不平回归风险
//  v10.0 双机并行架构
//    为什么能叠加带宽：rclone 里没有「两台协作跑同一个作业」这种东西，所以不去造。
//      改成把一个目录拆成互不重叠的子任务 —— 每片自己是一个完整的 sync/copy，
//      两台各跑各的。拆法是按源目录的一级子目录切，根下散着的文件用
//      _filter.ExcludeRule 单独成一片。每片的 srcFs/dstFs 都是真实路径，
//      不需要文件清单，不会漏也不会重
//    怎么分：先给每片称重（operations/size），再按实测带宽做加权 LPT ——
//      大片先放，放进「当前预计完工最早」的那台。实测 60:30 MB/s 两台、
//      300/100/50/10 GB 四片时分成 310 GB : 150 GB，比值 2.07:1，贴合权重 2:1。
//      按片数均分会得到 205:255，等于让快的那台干等
//    最大片最先开工：最长的活如果最后才开，它就变成收尾时谁也帮不上忙的长杆，
//      总时长退化成「最大单片耗时」。两级选片（自己的 / 偷来的）都取最大
//    工作窃取：一台干完自己名下的片，直接去拿另一台还没开工的。称重总有误差，
//      没有这一条就会出现一台闲着看另一台磨
//    故障转移：一台连挂 4 拍判掉线，它手上那片和名下没开工的片全部回公共队列，
//      另一台接着跑。已传完的文件重跑时被 rclone 跳过，不会重复搬运。
//      这是双机相对单机唯一真正的可靠性红利，也是「稳」的来源
//    一台同时只跑一片：并发度已经由该机的 Transfers/Checkers 表达了，
//      再叠作业只会把内存预算踩穿 —— 内存上限那张卡算的就是「一个作业」的峰值
//    合并而不是重写监控：两台的 core/stats 合成一份喂给原来的 render，
//      监控区 / 曲线 / 胶囊 / 进度一行未动。字节数要先并进 x.done 再切片，
//      否则下一片从零开始会让总字节倒退，render 会把整条曲线清空重来
//    每台各带一份调优：两台的核数、内存、上行往往不一样，共用一份等于按弱的那台配。
//      tune 改成「当前选中机位那份」的活引用，既有代码全都直接读写 tune.xxx，
//      一行业务代码没动
//    自检改成两台并行跑（一台慢不该拖着另一台的结果），新增第 5 行
//      「两台 Remote 一致」—— 这是分片能不能跑的硬前提。一台成一台败不算全败，
//      能跑就先按单机跑起来，坏的那台明确点出来
//    链路测速：延迟连打 5 次取中位；带宽从源 remote 拉进 rclone 的内存后端
//      :memory:，不落盘、不碰目标端、退出即消失，所以不需要任何清理动作，
//      也就不必为了测速去放开 purge 这类危险接口。时长 + 字节双闸限死，
//      最多吃内存上限的一半。结果直接进 weights() 决定分配比例
//    Remote 同步：新增 /api/migrate，源机 config/get → 目标机 config/create
//      全在 Worker 里闭环，token / client_secret / 密码一步都不经过浏览器，
//      与「config/get 只放行 type」那条既有约定一致
//    单机零回归：B 未启用时 live() 只有一台，分片规划整段跳过（多跑一轮 list
//      + 称重纯属浪费，还会让「开始传输」慢好几秒），所有下游走的都是原来那条路。
//      旧的扁平 cuven_cfg 和单份 cuven_tune 都会被认下来，老配置不丢
//  v10.1 两个自找的坑（都属于「这文件早写过警告」的那类）
//    · 注释里写了 ExcludeRule 的字面量，里面的星斜杠把块注释提前闭合了。
//      node --check 查不出来 —— 前端整段活在模板字符串里，外层看它只是字符串。
//      已把内联脚本的语法检查加进回归脚本
//    · join() 里用正则去尾斜杠，反斜杠被外层模板吃掉，正则当场废掉。
//      v5.5 与 v8.8 都栽过同一个坑，这次改成无正则实现
//    · tick 把每台的错误都在 Promise.all 里吃掉了，外层 catch 再也收不到异常，
//      紧急释压那条升级链变成死代码。改成显式判「这一拍有没有任何一台出新数据」，
//      并且没有新数据时不渲染 —— 渲染 0 等于让曲线撒谎
//  v10.2 版本改制：Engineer Edition → Cuven Plēthos
//    编号从日期式 26-0825n 换成 825 / (A)：日期后缀连排到第 14 个字母，
//      说明它早就不是「哪天构建的」而是「第几次改」，那就别再假装是日期。
//      825 是版本序列，括号里的字母是该序列下的修订
//    常量拆成 CORE + BUILD 再拼 VER：名字不动、编号每次都动，分开存才不会
//      每次改版号都要碰两处字面量。VER 同时供 /version、关于卡、
//      window.Cuven 三处消费，单一来源不变
//    关于卡补一句核心说明，走正文墨色；署名仍留在更淡的一档 ——
//      同一张卡里靠色阶分层，不靠字号，版面才不碎
//  v10.3 分片可见化 + 线路测速
//    分片清单：每个一级子目录一行，标着体积、在哪台、什么状态。
//      分片是这工具最不直观的一步，不摊开来，用户只看得到一个总速度，
//      出问题也说不清是哪一片卡住
//    手动改派：等待中的片点一下换机位并钉住，nextShard 不会再偷走钉住的片。
//      称重会误判（目录里全是小文件时字节数不大但耗时很长），这种时候
//      人比算法清楚。但机器掉线时连钉子一起解开 —— 钉着不放只会让那片永远等
//    测速拆成两个数，量的是两件事：
//      线路带宽 —— VPS 拉公共测速文件（HTTP → :memory:，多线程、取稳态峰值），
//        量裸管道。取峰值不取平均：前一两秒是慢启动和握手，算进去要压低两三成
//      源端读取 —— 从真正要传的 remote 拉，量这条具体路线的吞吐
//    权重仍然用源端读取。机房给 1Gbps 不代表源站会用 1Gbps 喂你，限速和地理
//      距离都在源站那侧，线路测速看不出来；只测过线路就退而用线路值
//    Ookla 做不到，说清楚而不是假装：它的协议要跑官方客户端，而面板到 VPS
//      只有 rclone rc 一条通道；Ookla 服务端也不接第三方工具。这里用的是同样
//      原理的公共大文件下载，口径一致，但不是 Ookla
//    白名单加两个：operations/copyfile（测速站没有索引页，sync/copy 会卡在
//      列目录上；copyfile 只搬指名文件，能力严格小于已放行的 sync/copy）、
//      fscache/clear（测完放掉 :memory:，否则 rclone 的 fs cache 会攥着
//      那一百多 MB 好几分钟，连测两台可能把小内存机器 OOM 掉）
//  v11.0 推倒重来：双机改成完全隔离
//    v10 的分片架构错在根上。它为了让两台协作跑「同一个任务」，被迫要求
//      两台看到同名同配置的 remote —— 于是长出一致性校验、配置迁移、
//      合并自检、共用调优、工作窃取、故障转移。每个补丁自己都讲得通，
//      合起来就是「问题太多」。耦合是因，补丁是果，只能从因上拆
//    新模型：两台各是一套完整的、互不知情的传输单元。各自的连接、remote、
//      调优、自检、测速、任务。谁也不需要认识谁，也就没有一致性这回事
//    删掉：分片编排器与运行器（buildPlan / assign / nextShard / pump /
//      evacuate / 工作窃取 / 分片清单 / 手动改派 / weights），
//      remote 一致性检查，下拉框取交集，合并自检行
//    顶部新增 A / B 分段控件，统辖一切：切一次，配置 / 诊断 / 测速 / 调优 /
//      remote / 传输表单全部换到那一台。界面在任何时刻只呈现其中一台 ——
//      上一版处处都要问「这说的是哪台」，根子就是一个界面同时说两台的事
//    每台各存一份：ck（自检四行的结论）、ckMsg、tune、remotes、bw/line/rtt、
//      cuven_form_<id>（传输表单）。切回来看到的是它自己的状态，不是空白，
//      也不是另一台的
//    typeCache 按机位分：隔离之后同名 remote 完全可以是不同类型
//      （A 的 dst 是 Dropbox、B 的 dst 是 WebDAV），共用一份会串味
//    断开只断当前这台：另一台还在传的话，凭什么把它一起掐了
//    Remote 复制从「前提」降级为「省事」：两台不需要一致，这只是免得
//      在另一台上重走一遍授权
//    传输视图是唯一同时显示两台的地方：机位读数条给出「哪台 · 多快 ·
//      到哪了 · 在传什么」，文件卡名字前缀标机位，切换条上的状态点跟着任务走
//    单机零回归：只启用一台时分段控件不出现，界面与单机版逐行等价
//  v11.1 重构中揪出的两个真问题
//    · 单台掉线的判定直接 x.ok = false —— 单机时这会把 live() 清空、
//      jobs 清空，整个会话无声无息变成「空闲」，紧急释压那条链根本没机会跑。
//      改成只有另一台还活着时才标掉线，单机交给 haltMiss 升级处理
//    · switchSrv 在 loadRemotes 落地前就调 restoreForm，回填时拿着上一台的
//      remotes 做校验，这台的源/目标被当成「已删除」丢掉。下拉框重建是异步的，
//      表单回填必须等它
//  v11.6 jobbar → 动作胶囊
//    转移页那张「路线 + 释压/暂停/停止」的卡撤掉，动作换成 action-capsule.html
//    那条胶囊，浮在导航坞正上方（与传输胶囊同一位置、互斥出现：那枚只在不看
//    转移页时出现，这条只在看转移页且有可用动作时出现），入场走原稿的
//    materialize —— 模糊 9px + 下移 14px + 缩 .962 一起收束，分隔线与三个动作
//    再按 55ms / 72ms 错峰跟上。
//    共享高亮、分隔线让位、按压回落、触发形变（未选中淡出失焦、选中区铺满整条、
//    图标换 ✓、文案换完成态并同步插值宽度）全部照抄，尺寸阴影时长曲线一个没换。
//    原稿没有退场，这里必须有（任务一结束胶囊就得走）：照入场那三支属性反过来、
//    压到 ~60% 时长走离场加速曲线
//    接线沿用本页既有那套「弹层背后挂原生控件」的路子：三格不实现业务，只去点
//    藏起来的 #haltBtn / #pauseBtn / #stop（halted 时第一格换 #resumeAll），
//    显隐与文案也只从那几个按钮上读 —— 判断留在原处，多一份副本就多一处会漂的真相。
//    二次确认那一下不演完成态：第一下只是把按钮举起来，演成完成是在骗人，
//    所以只有真正落下的那一下才 fire()
//    路线 / 停滞 / 低速三行没跟着卡一起消失，收成监控区顶上的一小段无壳文本
//  v11.5 品牌配色 + 全局纸面
//    Transfer Surface 换品牌五色 #FF6633 / #F6821F / #222222 / #070033 / #FFFFFF：
//      已传 = 暖橙（#F6821F → #FF6633，越靠近连接条越烈）；未传 = 白到浅蓝
//      （#FFFFFF → #E9F1FA → #BBD6EF，方向由连接条指向外端）。
//      白到浅蓝在 sRGB 里是一条短且全程在亮部的路，不用像灰→橙那样另设中间站
//      去绕开脏色。冷暖对置还顺带把两段分开了：进度边界不靠明度差也读得出来 ——
//      灰→橙那版是同色系，外端一满饱和整片就分不清进度。
//      深色版与灰→橙版都试过：#070033 放进暖段远端做"热度坡"要穿过棕糊成脏土；
//      整段做深色又太重，是浅底页面上一块挖出来的洞。
//      连接条 #222222 + 白 ✓：它两侧各留一道白缝（卡底色），要压得住的是白
//      而不是段色，白连接条在这里会连着缝一起消失。百分比两边都用 #222222
//      （橙上 5.0:1 / 灰上 12:1），一副色通吃；原稿给白字兜底的暗投影去掉
//    两端淡出改缓出曲线并加宽（11% → 25%，四个中间停靠点）：眼睛对饱和色的
//      alpha 变化极敏感，线性斜坡在橙上会看出一条边。散焦层模糊 .062 → .135，
//      峰值相应从 .88 压到 .78 —— 摊得更开就不该再给足能量，否则结成一团雾；
//      散焦带自身的遮罩也加了内侧停靠点，交接跨度跟着拉长
//    未传段圈一道亮橙细虚线（#FF6633 1px dashed）：把"还没到的部分"画成一个
//      待填的轮廓。描边挂在 .ts-seg 上而不是另加一层 —— 全局 box-sizing:border-box，
//      JS 写的 width/height 已含边框，几何一行没改；.mat 是 inset:0 定位到内边距盒，
//      填色不会盖住这道线。它在遮罩层里面，所以两端跟着一起失焦，
//      不会在淡出区留一截硬边；完成态右段宽度归零，虚线自然消失
//    撤掉右上那两行（已用时间 / 文件总数）：三个读数占三个角，右上留白，
//      比四角塞满干净。predP 弹簧、两支 Focus、set() 接线一并删掉，不留死代码
//    全局纸面搬 focus-diffusion-ring：径向纸（#fff → #f8f8fa → #ececf1）
//      + 点阵，再用从中心衰减的径向遮罩把点往边上抹掉。
//      不能挂在 body 上 —— body 是 560 封顶居中的正文列，背景只铺那一列；
//      改挂 html 的两层固定伪元素，铺满视口且不跟着滚。点距 18px / 点径 1.5px /
//      不透明度 .20 是原稿在手机宽度下（viewBox 1000 缩到 ~390）实际算出的那一档
//  v11.4 Transfer Surface（进度条卡 + 四格读数 → 一个面）
//    原来这一段是两张卡五个盒子：条只是条，字只是字，进度和读数互不相识，
//    而且 pct/字节 与四格里的时间、速度、文件数是同一件事的五种说法。
//    合成一个面（搬 transfer-surface.html）：连接条停在哪儿就是进度到了哪儿，
//    百分比贴着它走、左边塞不下就越到右侧（交接走焦距不是位移），
//    字节压在面上、被已传段盖过就转白，四个读数守在面的四角。
//    动效口径照搬：同一个目标（进度）挂三条刚度不同的弹簧 —— 几何 180/25/.80、
//      亮度领先 340/30/.58、阴影滞后 108/24/1.05，层次由质量与阻尼自己长出来，
//      一行 delay 都不写；弹簧只 retarget 不 reset；文字只改焦距不改位置
//      （blur 升过阈值才换字）；扫光无缝循环 + S 曲线速度，经过连接处增益抬一档。
//    完成不是换一张图：右段收到 0，连接条压扁再变宽、自己长成圆，✓ 最后描出来；
//      中断走同一条路，只是圆变红且不描 ✓
//    进度不再吃 dispPct 那层缓动 —— 面本身挂着弹簧，再叠一层就是双重平滑，
//      条永远追不上数字。animate() 只把原始 tgtPct 喂给它
//    ETA ±3 秒才动：它本来就是估的，每秒抖一下只会让人盯着它看
//    舞台：浅底、包在卡里，与其他监控卡同一套壳。字号取原稿的桌面档
//      （.152/.118/.155/.20/.215）而不是移动档（.19/.15/.20/.25/.26）——
//      要小一号就换档，不是自己拍一个数：原稿两档的差别本来就是"条大时字相对小"。
//      浅底逼着改的只有三处，都是把原稿那一对颜色反过来用，没引入新色板：
//      白字→墨字、白连接条+深 ✓ → 深连接条+白 ✓、淡蓝辉光→深蓝投影。
//      强调色 #29B6F0 在白底只有 2.3:1，压到 #0A7FB2（4.5:1）；
//      速度那档灰 #A9A9A9 换 #74747C。条本身的材质与全部弹簧参数一律没动
//  v11.3 测速流程改造（口径搬自 speedtest.html，不动界面）
//    带宽 —— 原来取 core/stats 的 speed 的最大值，注释说是"峰值、避开慢启动"。
//      但 rclone 的 speed 是「总字节 / 总耗时」的累计平均，单调收敛，取 max
//      基本等于取最后一拍，慢启动一秒不落全算进去了。改成自己按字节差分算
//      瞬时速率，丢掉前 1500ms，再照 Ookla 那条老规矩砍掉最慢 30% / 最快 10%
//      取平均。时间基准优先用 core/stats 回的 elapsedTime（服务端时钟），
//      rc 往返的抖动就完全不进速率计算；样本 < 4 个时退回峰值
//    采样 —— 500ms 串行两个往返改成 400ms，core/stats 与 job/status 并发发，
//      且 job/status 每 3 拍才问一次。原来采样间隔被 RTT 拖得忽长忽短，
//      而差分算速率对间隔准确度是敏感的
//    延迟 —— 5 次全用 + 墙钟计时 → 12 次丢前 2 次（TLS / Worker 冷启动），
//      改用 Resource Timing 的 responseStart − requestStart（不含 JS 调度、
//      请求排队、读 body），ping 取最小值，新增抖动 = 相邻差的平均绝对值。
//      Worker 侧在 /api/rc 回 Server-Timing: vps;dur=<边缘→VPS 毫秒>，
//      前端减掉它 —— 于是「本地网络这一跳」和「边缘到 VPS」分开报，
//      终于分得清是我网差还是机器远
//    内存 —— MaxTransfer 流量闸门原来只挂在源端读取上，线路测速是裸奔的
//      （1GB 档 + 8 线程，千兆机十秒真能把整份拉进内存）。现在三段共用同一个
//      闸门 = 内存上限的一半且 ≤512 MiB，OOM 从「弹窗提醒」变成结构上不可能
//    新增目标端写入（上行）—— 这是原来缺得最狠的一段：传输瓶颈十有八九在
//      VPS → 目标端（限速 / 分块 / 批量提交），而一个数都没有。数据直接用线路
//      测速刚拉进 :memory: 的那份往目标端推，不额外占内存；Dropbox 沿用真实
//      传输那套 chunk_size 注入，口径对得上。副作用是会在目标目录写一个
//      cuven-bench.tmp，测完立刻删、finally 再兜一次。单流口径。
//      为此白名单加 operations/deletefile —— 能力严格小于已放行的 sync/move
//    fscache/clear 从每段结束挪到整轮结束：上行要复用线路那份，中间不能清
//  v11.2 传输流（Sankey）
//    转移页监控区新增一张「传输流」卡：来源构成 → 传输阶段 → 结局，三列守恒。
//    几何与动效 1:1 搬 sankey-flow.html —— (u,v) 单一布局、八档弹簧驱动几何、
//    连接/断开/数值/文字共享一条 timeline、共享 glow 层、marching 虚线主链路、
//    ambient 光晕、标签 blur morph、节点呼吸投影、细带最小 30px 命中区。
//    只改两处：形态锁竖排（正文宽 560 封顶，横排读不了 —— 这条后来在 v11.41 推翻了）；配色收回本页令牌
//    （蓝=还活着的数据 / 绿=已落地 / 灰=还没轮到 / 红=出错），不引第二套色板。
//    口径全部来自 core/stats，逐字节守恒：
//      已落盘 = bytes − Σtransferring[].bytes　传输中 = Σtransferring[].bytes
//      排队   = totalBytes − bytes
//    类型分桶靠 transferring[] 的文件名后缀，在文件离场那一刻结账（钩在 dropCard）；
//    还没轮到的文件类型未知，如实归「未开始」而不是按比例摊到各类型上。
//    出错归属：本拍 errors 的增量，指派给同拍离场里进度最低的那几个文件。
//    差额（开页前就传完的 / 一闪而过没进过 transferring 的）归「其他」，
//    这样三列的总和永远等于进度条上的那个数，两处读数不会打架。
//    三个口径 tab = 字节 / 文件 / 占比。点带子看单条流量与占比，点节点展开内联明细盘
//    （不做底部 sheet：坞与传输胶囊已经占着屏底）。
//    不可见时（切页 / 后台 / 监控区未显示）弹簧直接掷到终点并停帧，不与曲线抢 rAF。
//  v11.7 分隔带（rule）
//    卡片之间从"一段空白"改成"露出来的一条纸"：上下两条虚线发丝框住中间那段
//      页面纸底（html::after 的 18px 点阵），带子本身不画点 —— 纸层是
//      position:fixed 贴视口的，带子跟着页面滚，两套同 18px 的点阵相位会随
//      滚动漂移，叠在一起会一路闪；所以带子只出边界，纹理让给纸
//    两级，不靠粗细区分：分节之间两条线（换一章）、同组堆叠卡一条线（.rule.tight，
//      源 / 目标 / 模式仍是一个组，上两条会把组拆散）
//    分节那一档用 .ws .sec + .sec:has(.card)::before 画，无需改 HTML；
//      :has(.card) 放过「只有一个主按钮」的行动段（它和上面的表单是同一件事）。
//      原 .sec margin-top:38 让位给带子自己的 24 + 54 + 24
//    虚线节距 36 = 2×18，一段虚线正好压住一列点；左右出血到 body 横向 padding
//      之外再 mask 淡出，硬端点在窄屏会抢注意力
//    高对比档换整条实线发丝并压掉带高（虚线定不住边界，留白自己会说话）
//  v11.8 移除链路测速
//    整节删掉，不是藏起来：HTML 那一节、.bwbar 结果条、bench 提示气泡、
//      pingProbe / runBench / benchLine / benchWrite / benchRead / benchOne /
//      benchVerdict / renderBench 与测速文件选择器（TESTFILES + cuven_testfile）
//      一并清走；trimmedMean / median / edgeMs / memCap 只服务测速，跟着走
//    白名单收紧：operations/copyfile、operations/deletefile、fscache/clear
//      是当初专为测速放行的，前端已无调用方，从 RC_WHITELIST 摘掉
//      （HEAVY_RC 里的 copyfile 同步删）；能删掉的能力才是真的不会被误用
//    保留：SRV 上的 rtt / jit / vps / bw / up 五个字段与 saveCfg / loadCfg 的
//      读写。v2 配置结构是和双机版共用的，原样读进来、原样写回去，
//      换回双机版时那边的测速结果还在 —— 换版本不该顺带清配置
//  v11.9 排障 + 维护 → 「诊断工具」一张卡
//    两节本来就是同一件事的两半（都是发给 VPS 的 shell 命令、都按端口密码
//      即时生成），分成两节读起来像两个模块。合成一张卡、两组折叠：
