//      CutoffMode:CAUTIOUS）。不自己列文件、切清单：copy 本来就跳过已存在的文件，
//      下一批重发同一份 body 就接着走 —— 既不用维护「哪些搬过了」，也不会因为
//      清单过期而漏搬。CAUTIOUS 是「预判会超就不开新文件」，不会把一个文件剁一半
//    · 到量时 rclone 把作业记成失败、错误里写 max transfer limit reached。
