//      「第 1/2 批完成 · 已传 2.50 TB / 3.80 TB · 还剩 1.30 TB」+ 继续按钮 ——
//      两处走同一个 goRun，点一下就是那次人工确认
//  827q Emby 改用账号密码登录
//    API Key 那一栏换成用户名 + 密码：走 Users/AuthenticateByName 换一张 AccessToken，
//    之后所有请求照旧用 X-Emby-Token 带着它 —— 下游一行没改
//    · 登录那一下必须带 X-Emby-Authorization（Emby 的门票格式）。其余请求也带着：
//      服务器端的活动设备列表里会显示成「Cuven Transfer」而不是一个匿名 UA
//    · Pw 是明文字段（Emby 4.x / Jellyfin 都收这个），所以这条链路只该走 https ——
//      端口白名单那一关本来就把 http 与 https 分开了
//    · 令牌会过期（服务器重启、在别处退过登录都会吊销）。所以对外那层包了一手：
//      没令牌先登，撞 401 就清掉重登一次再重试 —— 不该让人自己去点一次登录才能继续。
//      实测把存档里的令牌清空后再点任意一个「扫描」，它自己换了张新的
//    · 账密一改，手里那张令牌就地作废，免得拿旧令牌去撞新账号
//    · 「配好了」的判定也跟着换：地址 + 一组账密才算配好，令牌是换来的、不算配置。
//      徽标多一档「待登录」
//  827r 修 Emby 扫描 404（真机报回来的）：子路径 + 扫描方式各留退路
//    报错是「Emby 扫描没发出去：Emby 返回 HTTP 404」。看不到那台机器，所以按
//    404 的两种可能各堵一条，两条都能自愈，不用人去理解为什么：
//    · 反代把 Emby 挂在子路径下（/emby 最常见）。原来地址栏把路径整段丢了 ——
//      粘 https://x/emby 只留下 x，于是登录、列库、扫描一起 404，看上去像
//      「服务器坏了」。现在子路径留着、随请求带上；登录时先按已存的前缀试，
//      404 再自动试根路径与 /emby，通了就写回地址栏（不写回去，下一次 grab()
//      从输入框取值会把它抹掉，扫描那几条又打回根路径 —— 这个坑现踩现修）
//    · 有的部署不认 Library/Refresh（关掉媒体库那套、或改过 API 面）。扫描改成
//      三条路依次试：Library/Refresh → 计划任务里的「扫描媒体库」
//      （ScheduledTasks 找 Key=RefreshLibrary，再 POST Running/{id}）→ 按库逐个
//      Items/{id}/Refresh。只有 404/400 才往下试：401 是令牌的事、403 是权限的事，
//      换条路一样不行。单库那颗按钮 404 时也退回这三条
//    · Worker 侧相应放行 ScheduledTasks 与 ScheduledTasks/Running/{id}（后者按形状约束），
//      子路径按 [A-Za-z0-9._/-]{0,64} 校验后拼在所有接口前面
//  827s 修 827r 带出来的登录回归（「刚刚还能登，现在登不上」）
//    上一版给登录加了前缀探测，但那圈循环写成了「非 404 就停」。根路径上挂着别的
//    服务时它回什么都有可能（401 / 403 / 502），一停就永远试不到真正的那个前缀 ——
//    等于把原本能登的情形也堵死了。现在把候选前缀全试完，谁都不早停
