const ICONS = {
  '/icon-180.png': ICON_180,
  '/icon-192.png': ICON_192,
  '/icon-512.png': ICON_512
};

/* ══════════════════ [907] 给「请求添加」用的服务端接口 /api/link/* ══════════════════
   请求添加 Worker（tj.cuven.us）在没人开着这个面板的时候也要能把一部片走完：
   剧集的「文件夹整理 → 检查完整性 → 文件夹重命名」、PikPak → Dropbox 的传输、两端核对、删 PikPak 那份。
   原来这些全在浏览器里跑（rcProxy 只是转发），这里把同一套东西搬到 Worker 自己身上：
     · 解析器（rnParse / rnEps / rnVerdict / rnJunk / rnFormat）是页面里那一份的原样副本
       （页面里写在模板字符串中、反斜杠是双写的；这里是单写的同一段代码，判决一模一样）
     · rclone 走同一台 VPS（vps2.cuven.us:8080），连接参数从 Worker 变量读，不写在代码里：
         LINK_KEY    和请求添加 Worker 共用的口令（请求头 x-cuven-link），没配就整组接口关着
         VPS_HOST    默认 vps2.cuven.us        VPS_PORT  默认 8080
         VPS_USER    默认 admin                VPS_PASS  rclone rcd 的密码（必填，设成「密钥」）
         RC_WEBDAV   默认 webdav:（传输的来源：PikPak 的 WebDAV）
         RC_PIKPAK   默认 pikpak:（整理 / 改名 / 删除：rclone 原生 pikpak 后端，WebDAV 桥改不了名，见 829g）
         RC_DROPBOX  默认 dropbox:              AUTO_DIR  默认 auto（两边都是这个文件夹）
     · 只认 auto 下面的一层名字：item / dir 里不许有斜杠和 ..，碰不到 auto 以外的东西
   接口（都是 POST JSON，回 JSON；出错回 { error }）：
     /api/link/ping                       连得上 VPS 没有
     /api/link/organize  { dir }          剧集文件夹里的广告文件（rnJunk 判的）删掉（进 PikPak 回收站）
     /api/link/check     { dir, total? }  完整性：rnVerdict 的判决（ok / short / unsure / busy / skip / nonvid / bare），
                                          文件夹名里没写 [全N集] 时用 total（索引库从帖子标题读到的）当基准
     /api/link/rename    { dir, tpl?, lang?, grp? }  按模板改名（默认发布名 rel / 英文 / Cuven®），回 { name, jobid? }
     /api/link/job       { jobid }        异步作业的进度：{ finished, success, error, bytes, total }
     /api/link/copy      { item, kind }   webdav:auto/<item> → dropbox:auto/<item>（kind = file / dir），回 { jobid }
     /api/link/verify    { item, kind }   两端的文件数和字节数对不对得上
     /api/link/purge     { item, kind }   删 PikPak 那份（pikpak: 后端默认进回收站）
     /api/link/exists    { item }         dropbox:auto 里还有没有它（不在了 = 已经被人工挪进 ram / ram2 发行了）
     [908] /api/link/jobs    { ids }          一次问好几个作业；作业没了（rclone 重启过）回 missing
     [908] /api/link/stop    { jobid }        停一个作业（没了也算停了）
     [909] /api/link/verify  逐个文件核对（源头用原生 pikpak 后端），回 missing / differ / extra；列失败回 502，不再算「不一致」
     [909] /api/link/copy    { from: 'pikpak', sizeOnly } 补传时可以改从原生 pikpak 后端拿、只按大小判断
     [908] /api/link/exists  { items }        一次看好几个（列一次 dropbox:auto）
     [908] 连 VPS 带重试（vpsFetch）；VPS_ALT 可选：同一台机器的备用入口（灰云子域名 / IP），重试时轮流走
     [908] rclone 自己回的错（job not found、directory not found…）回 422，不再和「VPS 连不上」一样回 502 */

const LINK_RC = new Set([
  'core/version', 'core/stats', 'job/status', 'job/stop',
  'operations/list', 'operations/size', 'operations/stat', 'operations/mkdir',
  'operations/deletefile', 'operations/purge', 'operations/copyfile',
  'sync/copy', 'sync/move'
]);

const linkCfg = env => ({
  host: String(env.VPS_HOST || 'vps2.cuven.us').trim(),
  /* [908] 同一台 VPS 的备用入口（可选）：比如一个不走 Cloudflare 代理的灰云子域名，或者 VPS 的 IP。
     主入口回 52x / 连不上时，重试轮流走它 */
  alt: String(env.VPS_ALT || '').trim(),
  port: parseInt(env.VPS_PORT || '8080', 10),
  user: String(env.VPS_USER || 'admin'),
  pass: String(env.VPS_PASS || ''),
  webdav: String(env.RC_WEBDAV || 'webdav:'),
  pikpak: String(env.RC_PIKPAK || 'pikpak:'),
  dropbox: String(env.RC_DROPBOX || 'dropbox:'),
  auto: String(env.AUTO_DIR || 'auto').replace(/^\/+|\/+$/g, '')
});

/** 服务端自己调 rclone rc：同样的 host / 端口护栏，自己的接口白名单，异步作业不占边缘的超时 */
async function linkRc(env, path, payload, ms) {
  const c = linkCfg(env);
  if (!LINK_RC.has(path)) return { ok: false, status: 400, error: '不允许的接口: ' + path };
  if (!/^[a-zA-Z0-9.\-]{1,253}$/.test(c.host) || isBlockedHost(c.host)) return { ok: false, status: 500, error: 'VPS_HOST 不对' };
  if (!ALLOWED_PORTS.has(c.port)) return { ok: false, status: 500, error: 'VPS_PORT 必须是 80/8080/8880/2052/2082/2086/2095 之一' };
  if (!c.pass) return { ok: false, status: 500, error: '还没配 VPS_PASS（rclone rcd 的密码）' };
  const alt = c.alt && /^[a-zA-Z0-9.\-]{1,253}$/.test(c.alt) && !isBlockedHost(c.alt) ? c.alt : '';
  const x = await vpsFetch({ hosts: [c.host, alt], port: c.port, path: path, timeout: ms || 25000,
                             auth: 'Basic ' + btoa(c.user + ':' + c.pass), body: JSON.stringify(payload || {}) });
  if (x.thrown) {
    if (x.timedOut) return { ok: false, status: 504, error: 'VPS 响应超时' };
    return { ok: false, status: 502, error: '连不上 VPS（' + (x.thrown && x.thrown.message || x.thrown) + '）' + (x.attempts > 1 ? '，已重试 ' + (x.attempts - 1) + ' 次' : '') };
  }
  const r = x.r, text = x.text;
  let data = null; try { data = JSON.parse(text); } catch (e) {}
  if (r.status === 401) return { ok: false, status: 502, error: 'VPS 认证失败（VPS_USER / VPS_PASS 不对）' };
  /* rclone 自己回的错（JSON 里有 error，比如 job not found / directory not found）是 4xx 语义：不是 VPS 坏了 */
  if (!r.ok) return { ok: false, status: data && data.error ? 422 : 502, rc: !!(data && data.error),
                      error: (data && data.error) || edgeErr(r.status, text, x.attempts - 1), data: data };
  return { ok: true, status: 200, data: data || {}, retried: x.attempts - 1 };
}

/** 一个异步作业的进度。rclone 重启过、作业没了：missing（调用方从头再来，不算 VPS 出错） */
async function linkJob(env, id) {
  const r = await linkRc(env, 'job/status', { jobid: id }, 15000);
  if (!r.ok) {
    if (r.rc && /job not found|not found/i.test(r.error || '')) return { finished: true, success: false, missing: 1, error: 'job not found' };
    return { error: r.error, status: r.status };
  }
  const s = r.data || {};
  const st = await linkRc(env, 'core/stats', { group: 'job/' + id }, 15000);
  const x = (st.ok && st.data) || {};
  return { finished: !!s.finished, success: !!s.success, error: s.error || '',
           bytes: Number(x.bytes) || 0, total: Number(x.totalBytes) || 0, speed: Number(x.speed) || 0 };
}

/** auto 下面的一层名字：不许斜杠、不许 ..、不许空 */
function linkName(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s || s === '.' || s === '..' || /[\/\\]/.test(s)) return '';
  return s.length > 255 ? '' : s;
}

/** 一个目录下的全部文件（递归），回 [{ path, name, size }] */
async function linkFiles(env, fs) {
  const r = await linkRc(env, 'operations/list', { fs: fs, remote: '', opt: { recurse: true, filesOnly: true, noModTime: true, noMimeType: true } }, 50000);
  if (!r.ok) throw Object.assign(new Error(r.error), { status: r.status, rc: !!r.rc, notFound: !!(r.rc && /not found|doesn't exist/i.test(r.error || '')) });
  return ((r.data && r.data.list) || []).map(f => ({ path: String(f.Path || f.Name || ''), name: String(f.Name || ''),
                                                  size: f.Size == null ? -1 : Number(f.Size) }));
}

/* [909] 两端逐个文件核对（代替以前只比总数和总字节）。
   以前的毛病（用户：「经常触发两端核对不一致，重新传输」）：
     · 任何一边列目录失败（WebDAV 列大目录慢、52x、VPS 正忙）都被当成「不一致」，于是整个重传
     · 源头用 WebDAV 列：PikPak 的 WebDAV 列表会缓存、会慢，刚删掉的垃圾文件还在列表里
     · 只比总数、总字节：Dropbox 那边多一个文件、大小写不同、Unicode 写法不同都算不一致，还看不出是哪个文件
   现在：
     · 源头用 rclone 原生 pikpak 后端列（API 直接给大小，快、不缓存）；列失败回 502（没核对成），不再回「不一致」
     · 逐个文件比路径和大小：路径按 Unicode NFC + 不分大小写比（Dropbox 不分大小写）
     · Dropbox 存不了的系统文件（desktop.ini / thumbs.db / .DS_Store / Icon\r / .dropbox*）和没下完的临时文件
       （.part / .!qB / .aria2 / .td / .bc! / .!ut / .crdownload）不算
     · Dropbox 那边多出来的文件不算不一致（只要 PikPak 那边的都到了、大小都对）
     · 回缺了哪些、哪些大小不对（各最多 30 个），请求添加据此补传、写进日志 */
const LINK_SKIP = /^(desktop\.ini|thumbs\.db|\.ds_store|icon\r|\.dropbox|\.dropbox\.attr)$/i;
const LINK_TEMP = /\.(part|!qb|aria2|td|td\.cfg|bc!|!ut|crdownload)$/i;
const linkKey = p => String(p || '').normalize('NFC').toLowerCase();
function linkCompare(src, dst) {
  const skip = f => LINK_SKIP.test(f.name) || LINK_TEMP.test(f.name);
  const S = new Map(), D = new Map();
  src.forEach(f => { if (!skip(f)) S.set(linkKey(f.path), f); });
  dst.forEach(f => { if (!skip(f)) D.set(linkKey(f.path), f); });
  const missing = [], differ = [];
  S.forEach((f, k) => {
    const g = D.get(k);
    if (!g) missing.push(f.path);
    else if (f.size >= 0 && g.size >= 0 && f.size !== g.size) differ.push({ path: f.path, src: f.size, dst: g.size });
  });
  let extra = 0;
  D.forEach((g, k) => { if (!S.has(k)) extra++; });
  const sum = m => { let t = 0; m.forEach(f => { if (f.size > 0) t += f.size; }); return t; };
  return { ok: S.size > 0 && !missing.length && !differ.length,
           src: { count: S.size, bytes: sum(S) }, dst: { count: D.size, bytes: sum(D) },
           missing: missing.slice(0, 30), missingCount: missing.length,
           differ: differ.slice(0, 30), differCount: differ.length, extra: extra };
}

async function linkApi(request, env, p) {
  if (!env.LINK_KEY) return json({ error: '这台传输 Worker 没开放 /api/link（没配 LINK_KEY）' }, 404);
  if (request.headers.get('x-cuven-link') !== String(env.LINK_KEY)) return json({ error: '口令不对' }, 401);
  if (request.method !== 'POST') return json({ error: '请用 POST' }, 405);
  let b = {};
  try { b = await request.json(); } catch (e) { return json({ error: '请求体不是 JSON' }, 400); }
  const c = linkCfg(env);
  const fail = (r) => json({ error: r.error || '出错了' }, r.status || 502);
  const at = (remote, name) => remote + c.auto + (name ? '/' + name : '');
  try {
    if (p === '/api/link/ping') {
      const r = await linkRc(env, 'core/version', {}, 15000);
      return r.ok ? json({ ok: 1, version: (r.data || {}).version || '', core: VER }) : fail(r);
    }

    if (p === '/api/link/organize' || p === '/api/link/check' || p === '/api/link/rename') {
      const dir = linkName(b.dir);
      if (!dir) return json({ error: 'dir 不对（只能是 ' + c.auto + ' 下面的一层名字）' }, 400);
      if (p === '/api/link/rename') {
        const tpl = ['rel', 'std', 'season', 'nest', 'dot'].indexOf(b.tpl) >= 0 ? b.tpl : 'rel';
        const lang = ['en', 'cn', 'cnen'].indexOf(b.lang) >= 0 ? b.lang : 'en';
        const grp = b.grp == null ? 'Cuven®' : String(b.grp).slice(0, 40);
        const name = linkName(rnFormat(rnParse(dir), tpl, lang, grp));
        if (!name || name === dir) return json({ name: dir, same: 1 });
        const r = await linkRc(env, 'sync/move', { srcFs: at(c.pikpak, dir), dstFs: at(c.pikpak, name), deleteEmptySrcDirs: true, _async: true }, 30000);
        return r.ok ? json({ name: name, jobid: (r.data || {}).jobid }) : fail(r);
      }
      const files = await linkFiles(env, at(c.pikpak, dir));
      if (p === '/api/link/organize') {
        const junk = files.filter(f => rnJunk(f.name)).slice(0, 60);
        const done = [], errs = [];
        for (const f of junk) {
          const r = await linkRc(env, 'operations/deletefile', { fs: at(c.pikpak, dir), remote: f.path }, 20000);
          (r.ok ? done : errs).push(f.path);
        }
        return json({ files: files.length, deleted: done, failed: errs });
      }
      const pr = rnParse(dir);
      const total = parseInt(b.total, 10) || 0;
      if (!pr.total && total > 0) pr.total = total;
      const v = rnVerdict(pr, files.map(f => f.name));
      return json({ k: v.k, total: v.total || pr.total || 0, vids: v.vids || 0, have: v.have || [], miss: v.miss || [],
                    other: (v.other || []).slice(0, 20), part: (v.part || []).slice(0, 20), ongoing: !!pr.ongoing,
                    bytes: files.reduce((s, f) => s + f.size, 0) });
    }

    if (p === '/api/link/job') {
      const id = parseInt(b.jobid, 10);
      if (!id) return json({ error: '缺 jobid' }, 400);
      const j = await linkJob(env, id);
      return j.status ? fail(j) : json(j);
    }

    /* [908] 停一个作业（请求添加的看门狗：传输一小时没动静，先停掉再从头 copy；copy 会跳过已经传完的文件） */
    if (p === '/api/link/stop') {
      const id = parseInt(b.jobid, 10);
      if (!id) return json({ error: '缺 jobid' }, 400);
      const r = await linkRc(env, 'job/stop', { jobid: id }, 15000);
      if (!r.ok && !(r.rc && /not found/i.test(r.error || ''))) return fail(r);
      return json({ ok: 1 });
    }

    /* [908] 一次问好几个作业（请求添加每一轮只发一次）：{ ids: [..] } → { jobs: { id: 同 /api/link/job } }，最多 12 个 */
    if (p === '/api/link/jobs') {
      const ids = Array.from(new Set((Array.isArray(b.ids) ? b.ids : []).map(x => parseInt(x, 10)).filter(x => x > 0))).slice(0, 12);
      const jobs = {};
      await Promise.all(ids.map(async id => { jobs[id] = await linkJob(env, id); }));
      return json({ jobs: jobs });
    }

    /* [908] 一次看好几个还在不在 dropbox:auto（列一次目录）：{ items: [..] } → { exists: { name: 0 | 1 } } */
    if (p === '/api/link/exists' && Array.isArray(b.items)) {
      const names = b.items.map(linkName).filter(Boolean).slice(0, 200);
      const r = await linkRc(env, 'operations/list', { fs: at(c.dropbox), remote: '', opt: { noModTime: true, noMimeType: true } }, 50000);
      let have = new Set();
      if (r.ok) have = new Set(((r.data && r.data.list) || []).map(f => String(f.Name || f.Path || '')));
      else if (!(r.rc && /not found/i.test(r.error || ''))) return fail(r);     // auto 文件夹都不在 = 全都不在了
      const exists = {};
      names.forEach(n => { exists[n] = have.has(n) ? 1 : 0; });
      return json({ exists: exists });
    }

    const item = linkName(b.item);
    const kind = b.kind === 'dir' ? 'dir' : 'file';
    if (!item) return json({ error: 'item 不对（只能是 ' + c.auto + ' 下面的一层名字）' }, 400);

    if (p === '/api/link/copy') {
      await linkRc(env, 'operations/mkdir', { fs: c.dropbox, remote: c.auto }, 20000);
      /* [909] from: 'pikpak' —— 补传时改从 rclone 原生 pikpak 后端拿（WebDAV 列表里没有 / 拿不到的文件）；
         sizeOnly —— 只按大小判断要不要传（两个后端的修改时间对不上，不加这个会把传好的也重传一遍） */
      const srcRemote = b.from === 'pikpak' ? c.pikpak : c.webdav;
      const extra = b.sizeOnly ? { _config: { SizeOnly: true } } : {};
      const r = kind === 'dir'
        ? await linkRc(env, 'sync/copy', Object.assign({ srcFs: at(srcRemote, item), dstFs: at(c.dropbox, item), _async: true }, extra), 30000)
        : await linkRc(env, 'operations/copyfile', Object.assign({ srcFs: at(srcRemote), srcRemote: item, dstFs: at(c.dropbox), dstRemote: item, _async: true }, extra), 30000);
      return r.ok ? json({ jobid: (r.data || {}).jobid, from: b.from === 'pikpak' ? 'pikpak' : 'webdav' }) : fail(r);
    }

    if (p === '/api/link/verify') {
      /* [909] 源头默认用原生 pikpak 后端（src: 'webdav' 可以改回 WebDAV）；列失败 = 没核对成（502 / 422），不是不一致 */
      const srcRemote = b.src === 'webdav' ? c.webdav : c.pikpak;
      if (kind === 'dir') {
        let src, dst;
        try { src = await linkFiles(env, at(srcRemote, item)); }
        catch (e) { return json({ error: '核对时列 PikPak 那边失败：' + e.message, side: 'src' }, e.notFound ? 422 : 502); }
        try { dst = await linkFiles(env, at(c.dropbox, item)); }
        catch (e) {
          if (!e.notFound) return json({ error: '核对时列 Dropbox 那边失败：' + e.message, side: 'dst' }, 502);
          dst = [];                                                 // Dropbox 那边还没有这个文件夹 = 全缺
        }
        const cmp = linkCompare(src, dst);
        return json(Object.assign({ via: srcRemote }, cmp, { ok: cmp.ok ? 1 : 0 }));
      }
      const stat = async (remote) => {
        const r = await linkRc(env, 'operations/stat', { fs: at(remote), remote: item, opt: { noModTime: true, noMimeType: true } }, 30000);
        if (!r.ok) throw Object.assign(new Error(r.error), { status: r.status, notFound: !!(r.rc && /not found/i.test(r.error || '')) });
        const it = (r.data || {}).item;
        return it ? { size: it.Size == null ? -1 : Number(it.Size) } : null;
      };
      let s1, s2;
      try { s1 = await stat(srcRemote); }
      catch (e) { return json({ error: '核对时看 PikPak 那边失败：' + e.message, side: 'src' }, e.notFound ? 422 : 502); }
      if (!s1) return json({ error: 'PikPak 那边没有这个文件了：' + item, side: 'src' }, 422);
      try { s2 = await stat(c.dropbox); }
      catch (e) { if (!e.notFound) return json({ error: '核对时看 Dropbox 那边失败：' + e.message, side: 'dst' }, 502); s2 = null; }
      const differ = s2 && s1.size >= 0 && s2.size >= 0 && s1.size !== s2.size ? [{ path: item, src: s1.size, dst: s2.size }] : [];
      const ok = !!s2 && !differ.length;
      return json({ ok: ok ? 1 : 0, via: srcRemote, src: { count: 1, bytes: Math.max(0, s1.size) }, dst: { count: s2 ? 1 : 0, bytes: s2 ? Math.max(0, s2.size) : 0 },
                    missing: s2 ? [] : [item], missingCount: s2 ? 0 : 1, differ: differ, differCount: differ.length, extra: 0 });
    }

    if (p === '/api/link/purge') {
      const r = kind === 'dir'
        ? await linkRc(env, 'operations/purge', { fs: at(c.pikpak, item), remote: '' }, 30000)
        : await linkRc(env, 'operations/deletefile', { fs: at(c.pikpak), remote: item }, 20000);
      return r.ok ? json({ ok: 1 }) : fail(r);
    }

    if (p === '/api/link/exists') {
      const r = await linkRc(env, 'operations/stat', { fs: at(c.dropbox), remote: item, opt: { noModTime: true, noMimeType: true } }, 30000);
      if (!r.ok) return fail(r);
      return json({ exists: (r.data || {}).item ? 1 : 0 });
    }

    return json({ error: 'not found' }, 404);
  } catch (e) {
    return json({ error: (e && e.message) || String(e) }, (e && e.status) || 500);
  }
}

/* ── 解析器：页面里「文件夹整理 / 文件夹重命名」那一份的服务端副本（判决与页面一致） ── */
const RN_CND = { '零':0,'〇':0,'一':1,'二':2,'两':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9 };
function rnCn2n(s) {
  s = String(s || '').trim();
  if (/^[0-9]+$/.test(s)) return parseInt(s, 10);
  if (s.indexOf('十') >= 0) {
    const p = s.split('十');
    const a = p[0] === '' ? 1 : (RN_CND[p[0]] == null ? 0 : RN_CND[p[0]]);
    const b = !p[1] ? 0 : (RN_CND[p[1]] == null ? 0 : RN_CND[p[1]]);
    return a * 10 + b;
  }
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const d = RN_CND[s.charAt(i)];
    if (d == null) return 0;
    n = n * 10 + d;
  }
  return n;
}

/* 硬标签：见到它就说明标题已经念完了，后面全是规格。
   平台缩写（DSNP / NF / AMZN / MAX…）故意不收进来 —— "Mad Max" 里的
   Max 会把标题切成"Mad"。它们本来就落在硬标签后面，删不删都一样。 */
const RN_HARD = [
  /^[0-9]{3,4}[pi]$/,
  /^[48]k$/, /^uhd$/,
  /^x26[45]$/, /^h\.?26[45]$/, /^(hevc|avc|av1|vc-?1|xvid|divx|mpeg2?)$/,
  /^[0-9]{1,2}-?bits?$/, /^hi10p?$/,
  /^(web|web-?dl|webrip|bluray|blu-?ray|bdrip|brrip|bdmv|remux|bdremux|uhdbd|hdtv|dvdrip|dvdscr|dvd[59]?|hdrip|tvrip|hdts|vhsrip)$/,
  /^(ddp?\+?[0-9]?|dd\+|eac3|ac3|dts|dts-?hd(-?ma)?|dtshd|truehd|atmos|aac[0-9]?|flac[0-9]?|lpcm|opus|mp3)$/,
  /^[0-9]\.[0-9]$/,
  /^(hdr10?\+?|dovi|hlg|sdr)$/,
  /^(proper|repack|extended|uncut|unrated|remastered|complete|internal|limited|rerip|criterion|imax)$/,
  /^(mkv|mp4|avi|rmvb|iso|m2ts)$/
];
const rnHard = t => RN_HARD.some(re => re.test(t));

// 广告块的证据：域名、"发布 / 压制 / 论坛 / 字幕组"这类字眼、@ 开头的组名
const RN_AD = /(www\.|\.com|\.net|\.org|\.cc|\.top|\.xyz|\.tv|\.me|\.club|\.vip|\.info|\.win|\.site|\.pw|\.icu|\.co|发布|压制|论坛|字幕组|出品|分享|转载|首发|原创|下载|资源|电影天堂|剧集网|影视|@)/i;
// 中文规格标签：字幕语种、音轨、画质、版本 —— 全是标题之外的话
const RN_CJUNK = /(字幕|中字|双语|国语|粤语|日语|韩语|英语|配音|音轨|内封|内嵌|外挂|杜比|全景声|视界|版本|收藏|加长|删减|导演剪辑|重制|修复|高码|原盘|蓝光|超清|高清|画质|集全|完结|更新至|合集|简体|繁体|简繁|特效|附赠|无水印|官方)/;

/* 字幕语种：简繁英 → CN-HK-EN。长词排在短词前面，逐位贪婪匹配 ——
   「简体中文」要吃成 简体 + 中文（都是 CN，去重后一个），
   而不是 简 + 体 + 中 + 文 */
const RN_SUB = [
  ['简体','CN'], ['简中','CN'], ['简','CN'],
  ['繁体','HK'], ['繁中','HK'], ['繁','HK'],
  ['英文','EN'], ['英','EN'],
  ['日文','JP'], ['日语','JP'], ['日','JP'],
  ['韩文','KR'], ['韩语','KR'], ['韩','KR'],
  ['中文','CN'], ['中','CN']
];
function rnMapSub(seg, out) {
  let i = 0;
  while (i < seg.length) {
    let hit = null;
    for (let k = 0; k < RN_SUB.length; k++)
      if (seg.substr(i, RN_SUB[k][0].length) === RN_SUB[k][0]) { hit = RN_SUB[k]; break; }
    if (hit) { if (out.indexOf(hit[1]) < 0) out.push(hit[1]); i += hit[0].length; }
    else i++;
  }
  return out;
}
/* 在整条原名上找字幕标记，不管它在不在方括号里。
   「幻月字幕组」咬不到：字幕前面那两个字不在语种字符集里 */
function rnSubs(raw) {
  const out = [];
  const re = /[简繁中英日韩体文语]{1,10}(?:字幕|双语|三语|多语|双字|字)/g;
  let m;
  while ((m = re.exec(raw)))
    rnMapSub(m[0].replace(/(字幕|双语|三语|多语|双字|字)$/, ''), out);
  // 自己写出去的 [CN-HK-EN] 也要认得回来，否则改一次名就掉一次标签
  const back = /\[((?:CN|HK|TW|EN|JP|KR)(?:-(?:CN|HK|TW|EN|JP|KR))+|CN|HK|TW|EN|JP|KR)\]/g;
  while ((m = back.exec(raw)))
    m[1].split('-').forEach(c => { if (out.indexOf(c) < 0) out.push(c); });
  return out;
}

const RN_CJUNK_G = new RegExp(RN_CJUNK.source, 'g');

const RN_CJK = /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\uac00-\ud7af]/;

/* 括号块。规则按"这一块到底是什么"分四类，而不是一律删：
     · 纯年份            → 记下年份
     · 集数区间 01-12    → 记下集数
     · 广告 / 规格       → 丢
     · 开头第一块        → 丢（站点与压制组的固定位置：[BT-TV]、【幻月字幕组】）
     · 其余              → 还回 token 流，它多半就是标题
   第四条是关键：【间谍过家家】[Spy x Family] 这种，中文名和罗马音都在括号里，
   一律删就什么都不剩了。 */
function rnBrackets(s, hit) {
  let first = true;
  return s.replace(/[[(（【｛{]([^\])）】｝}]*)[\])）】｝}]/g, function (m, inner, at) {
    const lead = first && String(s).slice(0, at).trim() === '';
    first = false;
    const t = String(inner).trim();
    if (!t) return ' ';
    if (/^(19|20)[0-9]{2}$/.test(t)) { hit.year = hit.year || parseInt(t, 10); return ' '; }
    // 自己写出去的 [Full-4] 要认得回来：改成发布名之后完整性检查还得靠它
    let fm = /^full-([0-9]{1,4})$/i.exec(t);
    if (fm) { hit.total = hit.total || parseInt(fm[1], 10); return ' '; }
    let mm = /^(?:ep?)?([0-9]{1,4})\s*[-~至]\s*(?:ep?)?([0-9]{1,4})$/i.exec(t) || /^(?:ep?)([0-9]{1,4})$/i.exec(t);
    if (mm) {
      hit.ep = hit.ep || parseInt(mm[1], 10);
      if (mm[2]) hit.total = hit.total || parseInt(mm[2], 10);
      return ' ';
    }
    if (RN_AD.test(t) || RN_CJUNK.test(t)) return ' ';
    const toks = t.toLowerCase().split(/[\s._-]+/).filter(Boolean);
    if (toks.length && toks.every(rnHard)) return ' ';
    if (lead && String(s).slice(at + m.length).trim() !== '') return ' ';
    return ' ' + t + ' ';
  });
}

function rnParse(raw) {
  const src = String(raw == null ? '' : raw).trim();
  const hit = { year: 0, season: 0, season2: 0, ep: 0, total: 0, ongoing: false,
                res: '', hdr: [] };
  let s = src;

  s = s.replace(/\.(mkv|mp4|avi|ts|m2ts|iso|rmvb|mov|wmv)$/i, '');
  s = rnBrackets(s, hit);
  s = s.replace(/(https?:\/\/)?(www\.)?[a-z0-9-]+\.(com|net|org|cc|top|xyz|tv|me|club|vip|info|win|site|pw|icu|co|cn|io|la)\b/ig, ' ');
  s = s.replace(/@[A-Za-z0-9_-]+/g, ' ');

  /* 中文季集标记：只取值，不当切点 —— 它常夹在中文名和英文名中间
     （黑道新上路.第一季.Deli.Boys.S01…），在这里切会把英文标题一起丢掉 */
  s = s.replace(/第\s*([0-9一二三四五六七八九十两]{1,3})\s*季/g, function (m, d) {
    if (!hit.season) hit.season = rnCn2n(d); return ' ';
  });
  s = s.replace(/\bseasons?\s*[._-]?\s*([0-9]{1,2})\b/ig, function (m, d) {
    if (!hit.season) hit.season = parseInt(d, 10); return ' ';
  });
  s = s.replace(/第\s*([0-9一二三四五六七八九十两]{1,4})\s*集/g, function (m, d) {
    if (!hit.ep) hit.ep = rnCn2n(d); return ' ';
  });
  s = s.replace(/(全|共)\s*([0-9]{1,4})\s*集(全)?/g, function (m, a, n) {
    if (!hit.total) hit.total = parseInt(n, 10) || 0; return ' ';
  });
  s = s.replace(/([0-9]{1,4})\s*集全/g, function (m, n) {
    if (!hit.total) hit.total = parseInt(n, 10) || 0; return ' ';
  });
  /* 「更新至 8 集」不是总集数，是还在更新 —— 拿它当基准会把每一部在播的剧
     都判成不完整。记一个旗子，完整性检查直接跳过这类 */
  s = s.replace(/更新至\s*([0-9一二三四五六七八九十]{1,4})\s*集?/g, function () {
    hit.ongoing = true; return ' ';
  });
  s = s.replace(/(已?完结|全集|未删减|无删减)/g, ' ');

  /* 结尾的发布组：-BlackTV / -CMCT。只剥结尾那一段，
     "Spider-Man" 这类带连字符的标题在中间，咬不到 */
  s = s.replace(/[-@][A-Za-z0-9][A-Za-z0-9_@.®™]{0,19}\s*$/, function (m) {
    return /^[-@](the|a|an|and|of|part|ii|iii|iv)$/i.test(m.trim()) ? m : ' ';
  });

  const toks = s.split(/[\s._+~,]+/).filter(Boolean);

  /* 一趟扫完：年份 / 季 / 集在哪儿都要认（S01 常常排在年份后面，
     只扫到切点为止就会漏），但切点只认第一个 */
  let cut = -1;
  const maxY = new Date().getFullYear() + 2;
  for (let i = 0; i < toks.length; i++) {
    const t = toks[i], low = t.toLowerCase();
    let stop = false, m;
    if ((m = /^s([0-9]{1,2})e([0-9]{1,4})$/i.exec(t))) {
      if (!hit.season) hit.season = parseInt(m[1], 10);
      if (!hit.ep) hit.ep = parseInt(m[2], 10);
      stop = true;
    } else if ((m = /^s([0-9]{1,2})(?:-s?([0-9]{1,2}))?$/i.exec(t)) && i > 0) {
      if (!hit.season) { hit.season = parseInt(m[1], 10); hit.season2 = m[2] ? parseInt(m[2], 10) : 0; }
      stop = true;
    } else if ((m = /^([0-9]{1,2})x([0-9]{1,3})$/.exec(t))) {
      if (!hit.season) hit.season = parseInt(m[1], 10);
      if (!hit.ep) hit.ep = parseInt(m[2], 10);
      stop = true;
    } else if ((m = /^e(?:p)?([0-9]{1,4})(?:-e?p?([0-9]{1,4}))?$/i.exec(t)) && i > 0) {
      if (!hit.ep) hit.ep = parseInt(m[1], 10);
      if (m[2] && !hit.total) hit.total = parseInt(m[2], 10);
      stop = true;
    } else if (/^(19|20)[0-9]{2}$/.test(t)) {
      const y = parseInt(t, 10);
      if (y >= 1900 && y <= maxY) { if (!hit.year) hit.year = y; stop = true; }
    } else if (rnHard(low)) {
      stop = true;
    }

    // 切点不落在第 0 个：整段会被切没（"Web of Lies" 开头就是个硬标签）
    if (stop && cut < 0 && i > 0) cut = i;
  }
  const head = cut < 0 ? toks : toks.slice(0, cut);

  /* 中文 / 拉丁分流。空格只加在 token 边界上：同一个 token 里的
     「复仇者联盟」+「4」要粘成"复仇者联盟4"，跨 token 的
     「名侦探柯南」「绯色的子弹」之间才该有空格 */
  const cnP = [], enP = [];
  let last = 'l';
  for (let i = 0; i < head.length; i++) {
    /* 没进括号的中文规格词（「国语中字」「双语内封」）会混进标题区。
       只在"整块都是规格词"时丢：把已知规格词抠掉之后不剩东西才算。
       《修复的记忆》这类真标题抠掉「修复」还剩三个字，留着 */
    if (RN_CJK.test(head[i]) && head[i].replace(RN_CJUNK_G, '').length < 2) continue;
    const parts = rnRuns(head[i]);
    let cb = '', eb = '';
    for (let j = 0; j < parts.length; j++) {
      const p = parts[j];
      const k = p.k === 'n' ? last : p.k;
      if (k === 'c') { cb += p.t; last = 'c'; } else { eb += p.t; last = 'l'; }
    }
    if (cb) cnP.push(cb);
    if (eb) enP.push(eb);
  }
  return { raw: src, cn: rnTidy(cnP.join(' ')), en: rnTidy(enP.join(' ')),
           year: hit.year, season: hit.season, season2: hit.season2, ep: hit.ep,
           total: hit.total, ongoing: hit.ongoing,
           res: rnSpecs(src).res, hdr: rnSpecs(src).hdr, subs: rnSubs(src),
           tv: !!(hit.season || hit.ep || hit.total) };
}

/* 杜比视界写成中文时也要认（【杜比视界版本】），并按 DV → HDR10 → HLG 排序：
   同时有 DV 和 HDR10 的片子，发布名的惯例是 DV 在前 */
/* 分辨率与动态范围在原名上单独扫一趟，不跟着 token 流走 ——
   [1080P][AVC 8bit] 这种整块规格括号在剥括号那步就没了，
   跟着 token 流会一个也扫不到。分隔符里不含 +，否则 HDR10+ 会被劈开 */
function rnSpecs(raw) {
  const out = { res: '', hdr: [] };
  const H = { 'dv': 'DV', 'dovi': 'DV', 'dolbyvision': 'DV', '杜比视界': 'DV',
              'hdr10+': 'HDR10+', 'hdr10': 'HDR10', 'hdr': 'HDR', 'hlg': 'HLG' };
  const toks = String(raw || '').split(/[\s._~,\[\]()（）【】]+/);
  for (let i = 0; i < toks.length; i++) {
    const t = toks[i].toLowerCase();
    if (!out.res) {
      if (/^[0-9]{3,4}[pi]$/.test(t)) out.res = t;
      else if (t === '4k' || t === 'uhd') out.res = '2160p';
      else if (t === '8k') out.res = '4320p';
    }
    const h = H[t];
    if (h && out.hdr.indexOf(h) < 0) out.hdr.push(h);
  }
  if (/杜比视界|dolby\s*vision/i.test(raw) && out.hdr.indexOf('DV') < 0) out.hdr.push('DV');
  return { res: out.res, hdr: rnHdr(out.hdr) };
}

function rnHdr(a) {
  const rank = { 'DV': 0, 'HDR10+': 1, 'HDR10': 2, 'HDR': 3, 'HLG': 4 };
  return a.slice().sort((x, y) => rank[x] - rank[y]);
}

// 一个 token 拆成中文段 / 拉丁段 / 纯数字段（数字段跟着上一段的语言走）
function rnRuns(tok) {
  const out = [];
  let cur = '', kind = '';
  const chars = String(tok).split('');
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    const k = RN_CJK.test(ch) ? 'c' : 'l';
    if (k !== kind && cur) { out.push({ k: kind, t: cur }); cur = ''; }
    kind = k; cur += ch;
  }
  if (cur) out.push({ k: kind, t: cur });
  return out.map(function (p) {
    return (p.k === 'l' && /^[0-9]+$/.test(p.t)) ? { k: 'n', t: p.t } : p;
  });
}

function rnTidy(t) {
  return String(t || '').replace(/\s+/g, ' ').trim()
    .replace(/^[-–—·、。,.:：;；!！?？|/\\]+/, '')
    .replace(/[-–—·、。,.:：;；|/\\]+$/, '').trim();
}

/* 发布名模板：不是给刮削器看的，是把一条脏名字洗成干净的发布名 ——
   广告块、中文别名、平台、片源、音轨、编码全部丢掉，只留下
   标题 + 季 + 分辨率 + 动态范围，再把两类中文标签折成规范括号：
     [全4集]     → [Full-4]
     [简繁英字幕] → [CN-HK-EN]
   末尾换成自己的署名。目标形状：
     Worst.Ex.Ever.S02.2160p.HDR10.[Full-4][CN-HK-EN]-Cuven® */
function rnRelease(p, lang, grp) {
  let t;
  if (lang === 'en') t = p.en || p.cn;
  else if (lang === 'cnen') t = (p.cn && p.en) ? (p.cn + ' ' + p.en) : (p.cn || p.en);
  else t = p.cn || p.en;
  t = rnSafe(t).replace(/ /g, '.');
  if (!t) return '';
  const seg = [t];
  // 年份只在没有季号时写（剧集有 Sxx 就够了，惯例不再重复年份）
  if (p.year && !p.season) seg.push(String(p.year));
  if (p.season) {
    let sx = 'S' + (p.season < 10 ? '0' + p.season : p.season);
    if (p.season2) sx += '-S' + (p.season2 < 10 ? '0' + p.season2 : p.season2);
    else if (p.ep && p.ep <= 999 && !p.total) sx += 'E' + (p.ep < 10 ? '0' + p.ep : p.ep);
    seg.push(sx);
  }
  if (p.res) seg.push(p.res);
  for (let i = 0; i < p.hdr.length; i++) seg.push(p.hdr[i]);
  let tag = '';
  if (p.total) tag += '[Full-' + p.total + ']';
  if (p.subs && p.subs.length) tag += '[' + p.subs.join('-') + ']';
  const g = String(grp == null ? '' : grp).trim();
  return seg.join('.') + (tag ? '.' + tag : '') + (g ? '-' + g : '');
}

// 目录名里不能有的字符（Dropbox 最严：/ \ : ? * " < > |）
function rnSafe(t) {
  return String(t || '').replace(/[\\:*?"<>|/]/g, ' ')
    .replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
}

function rnFormat(p, tpl, lang, grp) {
  if (!p) return '';
  if (tpl === 'rel') return rnRelease(p, lang, grp);
  let t;
  if (lang === 'en') t = p.en || p.cn;
  else if (lang === 'cnen') t = (p.cn && p.en) ? (p.cn + ' ' + p.en) : (p.cn || p.en);
  else t = p.cn || p.en;
  t = rnSafe(t);
  if (!t) return '';
  const y = p.year ? String(p.year) : '';
  if (tpl === 'dot') return t.replace(/ /g, '.') + (y ? '.' + y : '');
  const base = y ? t + ' (' + y + ')' : t;
  // 跨季合集（S01-S09）不写季号：它不属于任何一季
  if (!p.season || p.season2) return base;
  const ss = p.season < 10 ? '0' + p.season : String(p.season);
  if (tpl === 'season') return base + ' S' + ss;
  if (tpl === 'nest') return base + '/Season ' + ss;
  return base;
}

/* ---------- 完整性检查：从文件名里抠集号 ----------
   这一段的判断会导向删除，所以宁可认不出、也不能认错。
   两道保险：① 先把会误伤的技术串整段盖掉（1080p / x265 / DDP5.1 / 年份），
   再按"集号该长什么样"逐级找；② 只认最有把握的那一级，找到就停 ——
   混着找等于把 5.1 的 1 和 E01 的 1 摆在一起投票。 */
const RN_VID = /\.(mkv|mp4|avi|ts|m2ts|m2t|mts|mov|wmv|flv|f4v|webm|rmvb|rm|iso|mpg|mpeg|mpe|m4v|vob|3gp|asf|ogm|ogv|mk3d|divx|strm)$/i;
// 没下完的文件。见到就整个文件夹弃权 —— 删一个正在下的目录是最坏的结果
const RN_PART = /\.(part|!qb|!ut|downloading|aria2|td|crdownload|tmp|bc!)$/i;

function rnEps(name) {
  const raw = String(name || '');
  if (!RN_VID.test(raw)) return null;                 // 非视频（nfo/srt/jpg）不参与
  let t = ' ' + raw.replace(RN_VID, '') + ' ';
  t = t.replace(/\b\d{3,4}[pi]\b/gi, ' ')             // 1080p / 480i
       .replace(/\bx?26[45]\b/gi, ' ')                // x264 / 265
       .replace(/\bh\.?26[45]\b/gi, ' ')
       .replace(/\b\d{1,2}-?bits?\b/gi, ' ')
       .replace(/\b(19|20)\d{2}\b/g, ' ')             // 年份
       .replace(/\b\d\.\d\b/g, ' ')                   // 5.1 / 7.1
       .replace(/\b(ddp?|dts|aac|eac3|ac3|flac|truehd|atmos)\+?\d?(\.\d)?\b/gi, ' ')
       .replace(/\b[48]k\b/gi, ' ')
       .replace(/\bhdr10\+?\b/gi, ' ');
  const out = [];
  const add = n => {
    n = parseInt(n, 10);
    if (n >= 0 && n <= 9999 && out.indexOf(n) < 0) out.push(n);
  };
  const sweep = re => { let m; while ((m = re.exec(t))) { add(m[1]); if (m[2]) add(m[2]); } };
  // ① S01E05 / S01E05-E06 / S01E05E06 —— 最没有歧义的一种
  sweep(/s\d{1,2}[\s._-]*e(\d{1,4})(?:[\s._-]*[-~]?[\s._-]*e?(\d{1,4}))?/ig);
  if (out.length) return out;
  // ② 第05集 / 第5话 / 第5期
  sweep(/第\s*(\d{1,4})\s*[集话話期]()/g);
  if (out.length) return out;
  // ③ E05 / EP05 / E05-E06（前面必须是分隔符，"Severance" 的 e 咬不到）
  sweep(/(?:^|[\s._\-[])e[p]?[\s._-]?(\d{1,4})(?:[\s._-]*-[\s._-]*e?p?(\d{1,4}))?(?=[\s._\-\]]|$)/ig);
  if (out.length) return out;
  // ④ [05] / 【05】
  sweep(/[[【]\s*(\d{1,4})\s*[\]】]()/g);
  if (out.length) return out;
  // ⑤ " - 05 " 番剧惯例
  sweep(/\s-\s*(\d{1,4})(?=\s|$)()/g);
  if (out.length) return out;
  // ⑥ 开头就是纯数字：01.mkv
  const m = /^\s*(\d{1,4})(?=[\s._-]|$)/.exec(t);
  if (m) add(m[1]);
  return out;
}

/* 判决。只有 short 一种会被拿去处理，其余一律弃权 —— 每一条弃权
   都对应一种真实存在的误判：
     skip   没有 [全N集] 可比，或还在更新
     busy   有没下完的文件
     empty  一个视频都没有（挂载没生效 / 目录结构不一样）
     unsure 视频数够了但集号认不出（中文名、无编号、单文件多集） */
function rnVerdict(p, names) {
  if (!p || !p.total || p.ongoing) return { k: 'skip' };
  const files = [], part = [], other = [];
  let vids = 0;
  for (let i = 0; i < names.length; i++) {
    const n = names[i];
    if (RN_PART.test(n)) { part.push(n); continue; }
    const e = rnEps(n);
    if (!e) { other.push(n); continue; }        // nfo / 字幕 / 海报 / 冷门格式
    vids++; files.push({ n: n, e: e });
  }
  if (part.length) return { k: 'busy', total: p.total, vids: vids, files: files, other: other, part: part };
  if (!vids) return { k: (names.length ? 'nonvid' : 'bare'), total: p.total,
                      vids: 0, files: [], other: other, part: [] };
  const have = {};
  files.forEach(f => f.e.forEach(x => { have[x] = 1; }));
  const miss = [];
  for (let i = 1; i <= p.total; i++) if (!have[i]) miss.push(i);
  const base = { total: p.total, vids: vids, files: files, other: other, part: [], miss: miss,
                 have: Object.keys(have).map(Number).sort((a, b) => a - b) };
  if (!miss.length) return Object.assign(base, { k: 'ok' });
  // 文件数够了却算出缺集，那多半是集号没认出来，不是真缺 —— 弃权
  if (vids >= p.total) return Object.assign(base, { k: 'unsure' });
  return Object.assign(base, { k: 'short' });
}

/* ── 垃圾文件判据 ──
   发布组塞进目录的东西分三层：能认出集号的视频（要留）、刮削器要用的配套
   （字幕 / nfo / 海报，也要留）、以及广告 —— 最新地址.txt、发布页.url、
   说明.html、二维码、招募启事。第三层才是这里要清的。
   判据保守到近乎胆小，三个条件全中才算垃圾：不是视频、不是配套、并且
   「扩展名本身就不该出现在剧集目录里」或者「名字里带招牌词」。
   认不出的一律留着 —— 这一步是删文件，宁可漏删，不可错删。
   招牌词用小写子串匹配而不是正则：本段在 Worker 里是模板字符串，
   词表里的点号若写进正则还要再转义一层，读的人迟早会漏掉一个。 */
const RN_KEEP = /\.(srt|ass|ssa|sub|idx|sup|vtt|smi|lrc|nfo|jpg|jpeg|png|webp|bmp|tbn|gif|cue|chp|json|xml)$/i;
const RN_TRASH = /\.(txt|url|htm|html|mht|lnk|exe|bat|cmd|scr|reg|vbs|jar|apk|db|ini|doc|docx|xls|xlsx|torrent|md|log|nfo\.bak)$/i;
/* 招牌词表。域名与「发布 / 论坛 / 资源」那一批直接复用上面清洗目录名时
   用的 RN_AD —— 同一套词汇，没必要维护两份。这里只补它没有的那些。 */
const RN_ADW = ['最新地址', '最新网址', '最新網址', '发布页', '發布頁', '求片', '招募',
  '广告', '廣告', '扫码', '掃碼', '微信', '公众号', '公眾號', '防走丢', '防走失', '防丢',
  '更多', '关注', '關注', '免费观看', '免費觀看', '影视大全', '点击', '點擊', '访问', '訪問',
  '说明', '說明', '必看', '入口', '接头', '接頭', 'telegram', 't.me', 'readme', 'read me',
  'check me', 'downloaded from', 'visit', 'http'];
function rnJunk(name) {
  const n = String(name || '');
  if (!n || RN_VID.test(n) || RN_PART.test(n)) return false;   // 视频与半成品：永不触碰
  if (RN_KEEP.test(n)) return false;                           // 配套：刮削器要用
  if (RN_TRASH.test(n)) return true;
  if (RN_AD.test(n)) return true;
  const low = n.toLowerCase();
  for (let i = 0; i < RN_ADW.length; i++) if (low.indexOf(RN_ADW[i]) >= 0) return true;
  return false;
}
const rnBase = p => { const a = String(p || '').split('/'); return a[a.length - 1]; };
